  $s$<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 160 120"><defs><linearGradient id="gditaeparenekopsht" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#BBDAE4"/><stop offset="1" stop-color="#EAF4F2"/></linearGradient></defs><rect x="0" y="0" width="160" height="120" fill="url(#gditaeparenekopsht)"/><circle cx="26.9" cy="22" r="10" fill="#FFF3D6"/><ellipse cx="118" cy="26" rx="14" ry="5" fill="#FFFFFF" opacity="0.85"/><circle cx="114" cy="22" r="6" fill="#FFFFFF" opacity="0.85"/><circle cx="123" cy="21" r="5" fill="#FFFFFF" opacity="0.85"/><path d="M0 81.6Q40 70.4 80 82.4T160 89.6V120H0Z" fill="#A6CDB4"/><path d="M0 101.1Q40 91.2 80 99.2T160 103.6V120H0Z" fill="#86B897"/><ellipse cx="80" cy="98" rx="30" ry="3" fill="#000000" opacity="0.08"/><g transform="translate(43 33) scale(1.15)"><rect x="40" y="12" width="6" height="14" rx="1" fill="#35504B"/><path d="M43 10Q40 4 44 0" fill="none" stroke="#EAF4F2" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" opacity="0.7"/><path d="M8 32L32 12L56 32Z" fill="#35504B"/><rect x="12" y="30" width="40" height="30" rx="1" fill="#35504B"/><rect x="18" y="38" width="9" height="9" rx="1.5" fill="#E07B5F"/><rect x="36" y="42" width="9" height="18" rx="1.5" fill="#EAF4F2"/><path d="M22.5 38V47M18 42.5H27" fill="none" stroke="#35504B" stroke-width="1" stroke-linecap="round" stroke-linejoin="round"/></g></svg>$s$,
