(
  $s$lejleku-qe-u-kthye$s$, 'sq', $s$Lejleku që u kthye në shtëpi$s$,
  $s$Çdo vjeshtë lejleku Bardhi fluturon deri në Afrikë, dhe çdo pranverë kthehet në të njëjtën fole mbi shtyllën e fshatit. Arta mëson se ata që duam kthehen.$s$,
  array[
    $s$Në një fshat të Myzeqesë, mes fushave të gjera e kanaleve plot me bretkosa, kishte një shtyllë të lartë druri pranë shkollës. Në majë të saj, prej sa mbanin mend pleqtë, ishte një fole e madhe lejleku, e ndërtuar me degë, kashtë dhe baltë. Dhe çdo pranverë, aty kthehej një lejlek i bardhë, me sqep të kuq e me këmbë të gjata.$s$,
    $s$Arta e vogël e quajti Bardhi. Shtëpia e saj ishte përballë shtyllës dhe çdo mëngjes, ndërsa hante bukë me gjalpë, e shikonte nga dritarja. Bardhi qëndronte në një këmbë, si një balerin, ose rregullonte folenë me sqep. Kur e ëma lejleke kthehej me ushqim, të dy kërcitnin sqepat: kra-kra-kra, si duartrokitje.$s$,
    $s$Atë verë, në fole lindën tre lejlekë të vegjël, gri e me pupla të ngatërruara. Arta i shikonte çdo ditë si rriteshin. Në fillim vetëm hapnin sqepat dhe kërkonin ushqim. Pastaj nisën të ngriheshin në këmbë. Pastaj të përplasnin krahët, në fillim ngadalë, pastaj gjithnjë e më fort, deri sa një mëngjes, i pari prej tyre u ngrit në ajër dhe bëri një xhiro mbi çatinë e shkollës.$s$,
    $s$Arta duartrokiti nga dritarja. «Gjyshe, gjyshe! Fluturoi!» Gjyshja erdhi pranë saj dhe buzëqeshi. «Tani do të mësojnë të fluturojnë larg», tha. «Se pas pak do të duhet të nisen.» «Ku do të shkojnë?» pyeti Arta. «Shumë larg, në Afrikë, ku dimri është i ngrohtë dhe bretkosat s'flenë.»$s$,
    $s$Arta u mërzit. Nuk donte që Bardhi të ikte. Por ditët u shkurtuan, gjethet e plepave u zverdhën, dhe një mëngjes shtatori, qielli u mbush me lejlekë. Ishin dhjetëra, qindra, që vinin nga fshatrat e tjera dhe fluturonin rrethore, gjithnjë e më lart. Bardhi dhe familja e tij u ngritën nga foleja dhe u bashkuan me ta.$s$,
    $s$Para se të ikte, Bardhi bëri një xhiro të fundit mbi shtëpinë e Artës. Ajo doli me vrap në oborr dhe tundi dorën me gjithë forcën. «Kthehu!» bërtiti. «Mos harro të kthehesh!» Lejlekët u bënë pika të vogla të bardha në qiell, dhe pastaj u zhdukën përtej maleve.$s$,
    $s$Foleja mbeti bosh gjithë vjeshtën. Pastaj ra shiu, erdhi era e ftohtë, dhe një natë dimri foleja u mbulua me borë, si një kapelë e bardhë. Arta e shikonte çdo mëngjes. «A do të kthehet vërtet?» pyeste gjyshen. «Do të kthehet», thoshte gjyshja. «Lejlekët s'e harrojnë kurrë shtëpinë. E gjejnë rrugën me diellin, me yjet dhe me zemrën.»$s$,
    $s$Gjyshja i tregoi edhe sa e gjatë ishte rruga e Bardhit. Fluturonte mbi male e mbi dete, mbi shkretëtirën ku rëra ishte e verdhë sa sheh syri, deri në fushat e mëdha të Afrikës, ku jetonin elefantë e zebra. «Atje ka ngrohtë», tha gjyshja, «por shtëpia e tij është këtu. Ai shkon atje vetëm për të kaluar dimrin.»$s$,
    $s$Arta vendosi të numëronte ditët. Çdo mbrëmje, para gjumit, vizatonte një vijë të vogël në një fletë të ngjitur pas murit. Vijat u bënë dhjetë, pastaj pesëdhjetë, pastaj njëqind. Dimri kaloi ngadalë, me borë, me ditë të shkurtra e me net të gjata pranë sobës.$s$,
    $s$Pastaj një mëngjes marsi, kur bajamet e oborrit kishin çelur lulet e para të bardha, Arta dëgjoi një tingull që e njihte: kra-kra-kra. Doli me vrap në oborr, me pizhame e zbathur. Në majë të shtyllës, mbi folenë e vjetër, qëndronte në një këmbë një lejlek i bardhë, me sqep të kuq.$s$,
    $s$«Bardhi!» thirri Arta. Lejleku uli kokën, pastaj e ngriti dhe kërciti sqepin, si të thoshte: «Ja ku jam. Të thashë se do të kthehesha.» Gjyshja doli pas saj me një batanije dhe ia hodhi mbi supe. «E sheh?» tha. «Ata që na duan, gjithmonë e gjejnë rrugën për t'u kthyer.»$s$,
    $s$Atë natë, Arta numëroi vijat në fletë. Ishin njëqind e shtatëdhjetë e dy. Pastaj e grisi fletën me buzëqeshje, se s'i duhej më. Nga dritarja, nën dritën e hënës, shihte Bardhin që flinte në një këmbë mbi folenë e tij. Dhe edhe Arta, e ngrohtë në shtratin e saj, fjeti e qetë, sepse shtëpia ishte përsëri e plotë.$s$
  ]::text[],
  array['nature', 'emotions']::text[], 0, 96, 9, null,
  $s$<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 160 120"><defs><linearGradient id="glejlekuqeukthye" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#D3E8CB"/><stop offset="1" stop-color="#F4F7EA"/></linearGradient></defs><rect x="0" y="0" width="160" height="120" fill="url(#glejlekuqeukthye)"/><circle cx="125.3" cy="22" r="10" fill="#FFF3D6"/><ellipse cx="34" cy="26" rx="14" ry="5" fill="#FFFFFF" opacity="0.85"/><circle cx="30" cy="22" r="6" fill="#FFFFFF" opacity="0.85"/><circle cx="39" cy="21" r="5" fill="#FFFFFF" opacity="0.85"/><path d="M0 84.2Q40 70.1 80 82.1T160 87V120H0Z" fill="#B5D39A"/><path d="M0 97.9Q40 92.4 80 100.4T160 96.2V120H0Z" fill="#93BE7B"/><circle cx="151.8" cy="104.3" r="1.6" fill="#FFFFFF" opacity="0.9"/><circle cx="25.3" cy="105.7" r="1.6" fill="#E58C8A" opacity="0.9"/><circle cx="40.7" cy="109.1" r="1.6" fill="#FFFFFF" opacity="0.9"/><circle cx="30.3" cy="115.7" r="1.6" fill="#E58C8A" opacity="0.9"/><circle cx="120.8" cy="115" r="1.6" fill="#E7B04B" opacity="0.9"/><circle cx="42" cy="110.7" r="1.6" fill="#E58C8A" opacity="0.9"/><circle cx="146.7" cy="107.2" r="1.6" fill="#FFFFFF" opacity="0.9"/><ellipse cx="80" cy="98" rx="30" ry="3" fill="#000000" opacity="0.08"/><g transform="translate(43 33) scale(1.15)"><ellipse cx="26" cy="28" rx="15" ry="8" fill="#3E5A38"/><path d="M12 26L2 30L12 31Z" fill="#3E5A38"/><path d="M37 25Q44 18 42 9" fill="none" stroke="#3E5A38" stroke-width="4.5" stroke-linecap="round" stroke-linejoin="round"/><circle cx="43" cy="8" r="4.2" fill="#3E5A38"/><path d="M46 9L60 15" fill="none" stroke="#E58C5A" stroke-width="2.6" stroke-linecap="round" stroke-linejoin="round"/><circle cx="44" cy="7" r="1" fill="#F4F7EA"/><path d="M24 35L22 60M30 35L32 60" fill="none" stroke="#E58C5A" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/><path d="M14 28Q24 33 34 30" fill="#F4F7EA" opacity="0.3"/></g></svg>$s$,
  'published', false, 660, 'editor'
),
(
  $s$rapunceli$s$, 'sq', $s$Rapunceli$s$,
  $s$Sipas vëllezërve Grim: një vajzë me flokë shumë të gjatë jeton e mbyllur në një kullë pa derë, derisa një këngë e saj arrin te zemra e dikujt jashtë.$s$,
  array[
    $s$Na ishin një herë një burrë e një grua që prisnin një fëmijë. Nga dritarja e shtëpisë së tyre shihej një kopsht i bukur, plot me lule e me perime, i rrethuar me një mur të lartë. Kopshti ishte i një magjistareje të fuqishme, që s'e lejonte askënd të hynte.$s$,
    $s$Një ditë, gruaja pa në kopsht një bimë me gjethe të gjelbra që quhej rapunzel, një lloj sallate. I pëlqeu aq shumë, sa nuk mendonte dot për asgjë tjetër. Burri, që e donte shumë, kapërceu murin një natë dhe i mori një grusht. Por natën tjetër, kur u kthye të merrte edhe pak, gjeti përpara magjistaren.$s$,
    $s$«Si guxon të vjedhësh në kopshtin tim?» bërtiti ajo. Burri u lut e u përgjërua. «Mirë», tha magjistarja, «merr sa të duash. Por kur të lindë fëmija, do të ma japësh mua. Do të kujdesem për të si nënë.» Burri, i tmerruar, pranoi. Dhe kur lindi një vajzë, magjistarja erdhi, e mori dhe e quajti Rapuncel, si bima e kopshtit.$s$,
    $s$Rapunceli u rrit dhe u bë vajza më e bukur nën diell. Kur mbushi dymbëdhjetë vjeç, magjistarja e mbylli në një kullë në mes të pyllit. Kulla s'kishte as derë, as shkallë, vetëm një dritare të vogël në majë. Kur magjistarja donte të hynte, qëndronte poshtë dhe thërriste: «Rapuncel, Rapuncel, lëshoji flokët!»$s$,
    $s$Rapunceli kishte flokë të gjatë e të mrekullueshëm, të artë si fije ari. Kur dëgjonte zërin e magjistares, i zgjidhte gërshetat, i mbështillte rreth një grepi në dritare dhe i lëshonte poshtë, njëzet metra. Dhe magjistarja ngjitej nëpër to.$s$,
    $s$Rapunceli kalonte ditët e gjata e të vetmuara duke kënduar. Këndonte për zogjtë që i vinin në dritare, për retë që kalonin, për pyllin që s'e kishte prekur kurrë. Dhe zëri i saj ishte aq i ëmbël, sa ndalnin edhe drerët për ta dëgjuar.$s$,
    $s$Pas disa vitesh, një princ kaloi me kalë nëpër pyll dhe dëgjoi këngën. Ishte aq e bukur, sa ndaloi dhe e dëgjoi gjatë, pa lëvizur. Kërkoi derën e kullës, por s'e gjeti. Kthehej çdo ditë për ta dëgjuar. Dhe një ditë, i fshehur pas një peme, pa magjistaren dhe dëgjoi: «Rapuncel, Rapuncel, lëshoji flokët!»$s$,
    $s$Atë mbrëmje, kur ra muzgu, princi u afrua te kulla dhe thirri: «Rapuncel, Rapuncel, lëshoji flokët!» Flokët u lëshuan, dhe princi u ngjit. Rapunceli u tremb, se s'kishte parë kurrë një djalë. Por princi i foli me butësi. I tregoi se si këngët e saj ia kishin prekur zemrën, dhe se donte vetëm të ishte shoku i saj. Dhe Rapunceli, që s'kishte pasur kurrë shok, pranoi.$s$,
    $s$Princi vinte çdo mbrëmje. I tregonte për botën jashtë kullës: për qytetet, për detin, për tregjet me fruta, për lumenjtë. Dhe Rapunceli i tregonte për zogjtë e saj dhe për këngët që shkruante. Një mbrëmje, Rapunceli i tha: «Dua të dal nga kjo kullë. Më sill çdo herë që vjen një fije mëndafshi. Do të thur një shkallë dhe do të zbres me ty.»$s$,
    $s$Por magjistarja e zbuloi sekretin. U zemërua aq shumë, sa i preu flokët Rapuncelit me gërshërë dhe e çoi në një shkretëtirë të largët, ku duhej të jetonte vetëm. Atë mbrëmje, kur princi thirri «Rapuncel, lëshoji flokët!», magjistarja lëshoi poshtë gërshetat e prera. Princi u ngjit, dhe në vend të Rapuncelit gjeti magjistaren. «Zogu yt i bukur ka fluturuar», i tha ajo. «Nuk do ta shohësh më kurrë.»$s$,
    $s$Princi u hodh nga dritarja e kullës, i dëshpëruar. Ra mbi një shkurre me gjemba, që ia gërvishtën sytë, dhe nga ajo ditë nuk shihte dot. Por zemra e tij vazhdonte ta kërkonte. Endej nëpër pyje e fusha, i verbër e i lodhur, duke ngrënë vetëm rrënjë e kokrra, dhe duke dëgjuar çdo zë që i ngjante zërit të saj.$s$,
    $s$Pas shumë kohësh, arriti në shkretëtirën ku jetonte Rapunceli. Dhe dëgjoi një zë që këndonte. E njohu menjëherë. Ndoqi zërin, hap pas hapi, derisa Rapunceli e pa dhe vrapoi drejt tij. E përqafoi fort dhe qau. Dy lotë të saj i ranë princit në sy, dhe papritur, sytë e tij u shëruan. Pa përsëri, më qartë se kurrë: dhe gjëja e parë që pa, ishte fytyra e saj.$s$,
    $s$Princi e çoi Rapuncelin në mbretërinë e tij, ku i pritën me gëzim të madh. Rapunceli gjeti edhe prindërit e saj të vërtetë, që e kishin kërkuar gjithë jetën. Flokët iu rritën përsëri, por ajo i mbante të shkurtër, të lirë e të lehtë. «Tani», thoshte, «s'kam më nevojë për flokë të gjatë. Kam derë, kam shkallë dhe kam gjithë botën.»$s$,
    $s$Dhe çdo mbrëmje, nga dritarja e pallatit, Rapunceli këndonte. Jo më nga vetmia, por nga gëzimi. Dhe zogjtë e pyllit vinin përsëri ta dëgjonin, si dikur.$s$
  ]::text[],
  array['classic', 'adventure']::text[], 48, 120, 10, null,
  $s$<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 160 120"><defs><linearGradient id="grapunceli" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#CBE0D3"/><stop offset="1" stop-color="#EDF3EC"/></linearGradient></defs><rect x="0" y="0" width="160" height="120" fill="url(#grapunceli)"/><path d="M11.2 47.2L21.2 100H1.2Z" fill="#5F8C76" opacity="0.85"/><circle cx="24.3" cy="72.2" r="18.5" fill="#8FB5A0" opacity="0.85"/><path d="M34.3 44.7L44.3 100H24.3Z" fill="#5F8C76" opacity="0.85"/><path d="M45.7 51.1L55.7 100H35.7Z" fill="#8FB5A0" opacity="0.85"/><path d="M117.1 39.3L127.1 100H107.1Z" fill="#5F8C76" opacity="0.85"/><path d="M131.2 50.9L141.2 100H121.2Z" fill="#8FB5A0" opacity="0.85"/><circle cx="144.9" cy="74.9" r="16.7" fill="#8FB5A0" opacity="0.85"/><path d="M0 97.6Q40 93.6 80 99.6T160 98.4V120H0Z" fill="#5F8C76"/><ellipse cx="80" cy="98" rx="30" ry="3" fill="#000000" opacity="0.08"/><g transform="translate(43 33) scale(1.15)"><rect x="20" y="18" width="24" height="42" rx="0" fill="#2C463B"/><path d="M16 18L32 0L48 18Z" fill="#D9644A"/><rect x="27" y="24" width="10" height="10" rx="5" fill="#EDF3EC"/><path d="M37 30Q46 40 40 50Q36 58 42 62" fill="none" stroke="#E7B04B" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/><path d="M20 44H44M20 52H44" fill="none" stroke="#EDF3EC" stroke-width="1" stroke-linecap="round" stroke-linejoin="round" opacity="0.3"/></g></svg>$s$,
  'published', false, 670, 'editor'
),
(
  $s$zemerimi-i-vogel-i-lines$s$, 'sq', $s$Stuhia e vogël e Linës$s$,
  $s$Kur Lina zemërohet, ndjen një stuhi brenda vetes, me rrufe e me erë. Gjyshja i mëson si ta qetësojë stuhinë pa e mbyllur, me frymë, me fjalë dhe me pak durim.$s$,
  array[
    $s$Lina ishte zakonisht një vajzë e qetë. Por ndonjëherë, brenda saj, ndodhte diçka. Ishte si një stuhi. Fillonte në bark, si një re e vogël gri. Pastaj ngjitej në gjoks, gjithnjë e më e madhe, me erë e me rrufe. Dhe kur arrinte në kokë, Lina bërtiste, hidhte lodrat në dysheme dhe përplaste dyert. Pastaj, kur stuhia kalonte, ndihej e lodhur dhe e trishtuar.$s$,
    $s$Atë pasdite, stuhia erdhi për shkak të një kulle. Lina kishte ndërtuar me kube kullën më të lartë që kishte bërë ndonjëherë, me një flamur të kuq në majë. Dhe vëllai i saj i vogël, Toni, që sapo kishte mësuar të ecte, kaloi pranë dhe e rrëzoi. Bum! Të gjitha kubet ranë në dysheme.$s$,
    $s$Stuhia u ngrit menjëherë. Lina ndjeu barkun që i nxehej, gjoksin që i shtrëngohej, faqet që i skuqeshin. «Toni!» bërtiti me gjithë forcën. «Ma prishe! Ma prishe gjithçka!» Dhe hodhi një kub drejt murit, aq fort sa bëri një shenjë të vogël. Toni filloi të qante, i trembur. Dhe Lina vrapoi në dhomën e saj dhe përplasi derën.$s$,
    $s$Gjyshja e Linës, që po rrinte me ta atë ditë, trokiti butë në derë. «A mund të hyj?» Lina nuk u përgjigj. Gjyshja hyri gjithsesi, ngadalë, dhe u ul në buzë të shtratit. Lina ishte në qoshe, me fytyrën te gjunjët. «Kjo ishte një stuhi e madhe», tha gjyshja. Lina ngriti kokën, e habitur. «Si e di?»$s$,
    $s$«Sepse edhe unë kam stuhi», tha gjyshja. «Të gjithë kanë. Edhe mamaja jote, edhe babai yt. Zemërimi është si moti, Lina. Vjen e shkon. Nuk ka asgjë të keqe që vjen. E rëndësishme është çfarë bën kur je në mes të stuhisë.» Lina u mendua. «Unë hodha kubin», tha me zë të vogël. «Dhe bërtita. Dhe Toni qau.»$s$,
    $s$«Po», tha gjyshja. «Ishe e zemëruar, dhe kishe të drejtë të zemëroheshe. Kulla jote ishte e bukur dhe Toni e prishi. Por kur hodhe kubin, stuhia jote shkoi te muri dhe te Toni. A do të të mësoj një sekret për stuhitë?» Lina tundi kokën, me sy të lagur.$s$,
    $s$«Sekreti i parë është fryma», tha gjyshja. «Kur ndjen që stuhia po ngrihet, merr frymë thellë, sikur po nuhat një lule. Pastaj nxirre ngadalë, sikur po fryn një qiri, por pa e shuar. Lule, qiri. Lule, qiri. Provo.» Lina provoi. Nuhati një lule të padukshme. Fryu një qiri të padukshëm. Një herë, dy herë, tri herë. Dhe ndjeu që gjoksi i shtrëngohej pak më pak.$s$,
    $s$«Sekreti i dytë», tha gjyshja, «është t'i japësh emër stuhisë. Ta thuash me fjalë. Jo me kube, jo me britma, por me fjalë. Unë jam e zemëruar sepse... Provo.» Lina u mendua. «Unë jam e zemëruar sepse Toni ma rrëzoi kullën, dhe unë kisha punuar shumë.» «Shumë mirë», tha gjyshja. «E sheh? Kur e thua me fjalë, stuhia del jashtë pa thyer asgjë.»$s$,
    $s$«Dhe sekreti i tretë?» pyeti Lina, që tani ishte pak më e qetë. «Sekreti i tretë», tha gjyshja, «është të presësh. Stuhitë kalojnë gjithmonë. Mjafton të presësh pak, në një vend të qetë, derisa dielli të dalë përsëri. Ti e bëre këtë kur erdhe në dhomë. Ishte zgjedhje e mirë.»$s$,
    $s$Lina rrinte e heshtur. Stuhia brenda saj ishte bërë një re e vogël, që po largohej ngadalë. Pastaj kujtoi Tonin, që kishte qarë i trembur. «Gjyshe», tha, «Toni është i vogël. Nuk e dinte që kulla ishte e rëndësishme. Ai vetëm donte të luante me mua.» Gjyshja buzëqeshi. «Ke të drejtë. Ç'mendon të bësh?»$s$,
    $s$Lina doli nga dhoma. Toni ishte në dysheme, në qoshen e sallonit, ende me sy të kuq, duke mbajtur një kub në dorë. Lina u ul pranë tij. «Më fal që bërtita, Toni», i tha. «Isha shumë e zemëruar. Por s'duhej të bërtisja.» Toni e shikoi, pastaj ia zgjati kubin. Lina qeshi. «A do të ndërtojmë një kullë bashkë?» Toni tundi kokën me entuziazëm.$s$,
    $s$Ndërtuan një kullë të re, këtë herë të dy bashkë. Lina vinte kubet, dhe Toni i jepte. Kur kulla u bë e lartë, Lina i tha Tonit: «Dhe tani, a do ta rrëzosh ti?» Toni u ngazëllye aq shumë, sa i ra në mes me të dyja duart. Bum! Dhe të dy qeshën aq shumë, sa gjyshja doli nga kuzhina për të parë çfarë kishte ndodhur.$s$,
    $s$Atë natë, para gjumit, Lina i tregoi mamasë për stuhinë dhe për tre sekretet e gjyshes. «Fryma, fjalët dhe durimi», tha. «Lule, qiri.» Mamaja e përqafoi. «Do të të them një sekret të katërt», i tha. «Edhe kur ke stuhi, unë të dua njësoj. Edhe kur je e zemëruar, edhe kur bërtet. Gjithmonë.» Lina mbylli sytë. Brenda saj, qielli ishte i qetë, me yje. Natën e mirë, Lina.$s$
  ]::text[],
  array['emotions', 'lessons']::text[], 36, 96, 10, 'cloud',
  $s$<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 160 120"><defs><linearGradient id="gzemerimiivogelilines" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#BBDAE4"/><stop offset="1" stop-color="#EAF4F2"/></linearGradient></defs><rect x="0" y="0" width="160" height="120" fill="url(#gzemerimiivogelilines)"/><circle cx="132.5" cy="22" r="10" fill="#FFF3D6"/><ellipse cx="34" cy="26" rx="14" ry="5" fill="#FFFFFF" opacity="0.85"/><circle cx="30" cy="22" r="6" fill="#FFFFFF" opacity="0.85"/><circle cx="39" cy="21" r="5" fill="#FFFFFF" opacity="0.85"/><path d="M0 86.1Q40 78.1 80 90.1T160 87.1V120H0Z" fill="#A6CDB4"/><path d="M0 101.7Q40 89.9 80 97.9T160 99.8V120H0Z" fill="#86B897"/><ellipse cx="80" cy="98" rx="30" ry="3" fill="#000000" opacity="0.08"/><g transform="translate(43 33) scale(1.15)"><circle cx="22" cy="30" r="11" fill="#35504B"/><circle cx="34" cy="24" r="14" fill="#35504B"/><circle cx="46" cy="32" r="10" fill="#35504B"/><rect x="12" y="30" width="44" height="12" rx="6" fill="#35504B"/><path d="M22 48L20 54M34 48L32 56M46 48L44 54" fill="none" stroke="#7FB8C6" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/><circle cx="30" cy="33" r="1.3" fill="#EAF4F2"/><circle cx="38" cy="33" r="1.3" fill="#EAF4F2"/></g></svg>$s$,
  'published', false, 680, 'editor'
),
(
  $s$dymbedhjete-princeshat-kercimtare$s$, 'sq', $s$Dymbëdhjetë princeshat kërcimtare$s$,
  $s$Sipas vëllezërve Grim: çdo mëngjes, dymbëdhjetë princeshat zgjohen me këpucë të grisura, edhe pse dera e dhomës ka qenë e kyçur. Një ushtar i thjeshtë vendos të zbulojë sekretin.$s$,
  array[
    $s$Na ishte një herë një mbret që kishte dymbëdhjetë vajza, njëra më e bukur se tjetra. Flinin të gjitha në një dhomë të madhe, me dymbëdhjetë shtretër në rresht, dhe çdo mbrëmje, kur ato shtriheshin, mbreti e kyçte derën me çelës. Por çdo mëngjes, kur e hapte, gjente diçka të çuditshme: këpucët e princeshave ishin të grisura, me tabanin të shpuar, sikur të kishin kërcyer gjithë natën.$s$,
    $s$Askush s'e dinte si ndodhte. Princeshat nuk thoshin asgjë. Vetëm buzëqeshnin e shikonin njëra-tjetrën. Mbreti, i habitur e pak i nevrikosur, shpalli: «Kushdo që zbulon ku kërcejnë vajzat e mia natën, do të marrë si nuse atë që zgjedh, dhe një ditë do të bëhet mbret.»$s$,
    $s$Erdhën shumë princa. Secilit iu dha një dhomë pranë dhomës së princeshave, që t'i ndiqte. Por çdo mbrëmje, para gjumit, princesha më e madhe u sillte një gotë me pije të ëmbël, dhe ata binin në një gjumë aq të thellë sa s'dëgjonin asgjë. Në mëngjes, këpucët ishin përsëri të grisura, dhe princat ktheheshin në shtëpi të turpëruar.$s$,
    $s$Një ditë, një ushtar i varfër, që po kthehej nga lufta i plagosur e pa para, takoi në rrugë një plakë. I dha gjysmën e bukës që kishte. Plaka e pyeti ku po shkonte. «Ndoshta do të provoj të zbuloj sekretin e princeshave», tha ai me shaka. «Atëherë dëgjo», tha plaka. «Mos e pi pijen që do të të japin. Dhe merr këtë mantel. Kur ta veshësh, do të bëhesh i padukshëm.»$s$,
    $s$Ushtari shkoi në pallat. E pritën mirë dhe në mbrëmje e çuan në dhomën pranë princeshave. Princesha më e madhe i solli gotën me pije. Ai u bë sikur e piu, por e derdhi fshehurazi në një sfungjer që kishte lidhur nën mjekër. Pastaj u shtri dhe filloi të gërhiste me zë të lartë, sikur flinte thellë.$s$,
    $s$Kur e dëgjuan të gërhiste, princeshat qeshën. U ngritën, hapën dollapët, veshën fustanet më të bukura, krehën flokët dhe veshën këpucë të reja kërcimi. Princesha më e vogël ishte pak e shqetësuar. «Nuk e di pse», tha, «por sonte kam një ndjenjë të çuditshme.» «Je frikacake», tha e madhja. «Shiko si gërhet. Ky s'zgjohet as me top.»$s$,
    $s$Princesha më e madhe trokiti mbi shtratin e saj, dhe shtrati u ul në dysheme, duke hapur një portë të fshehtë. Nën të ishin shkallë që zbrisnin në errësirë. Princeshat zbritën njëra pas tjetrës, me më të madhen përpara. Ushtari u ngrit, veshi mantelin e padukshëm dhe zbriti pas më të voglës. Në shkallë, i shkeli pa dashur fustanin. «Kush ma tërhoqi fustanin?» thirri ajo. «Mos u bëj budallaqe», tha e madhja. «U kape pas gozhdës.»$s$,
    $s$Në fund të shkallëve, ishte një rrugicë me pemë mrekullie. Degët e tyre ishin prej argjendi, dhe gjethet shkëlqenin e tingëllonin si zile të vogla. Ushtari theu një degë, që t'ia tregonte mbretit. Pemët bënë krak! «A e dëgjuat?» pyeti më e vogla. «Janë zogjtë që po festojnë», tha e madhja. Pastaj kaluan një pyll me pemë prej ari, dhe një tjetër me pemë prej diamanti. Ushtari theu një degë nga secili.$s$,
    $s$Arritën në breg të një liqeni të madh. Aty prisnin dymbëdhjetë barka, dhe në çdo barkë, një princ i bukur me rrema në duar. Ushtari hipi në barkën e princeshës më të vogël. «Nuk e di pse», tha princi duke vozitur, «por sonte barka më duket më e rëndë.» Përtej liqenit, ishte një kështjellë e ndriçuar, nga e cila vinte muzikë e gëzuar me tamburë e me trumbeta.$s$,
    $s$Hynë brenda, dhe gjithë natën, princeshat kërcyen me princat e tyre, deri sa këpucët iu grisën. Ushtari, i padukshëm, kërceu edhe ai mes tyre, dhe kur princeshës më të vogël i vunë një gotë me lëng frutash përpara, ai e piu fshehurazi. Ajo u tremb e u habit, por motrat qeshën përsëri.$s$,
    $s$Në orën tre të mëngjesit, kur këpucët ishin plot vrima, princeshat u përshëndetën me princat dhe u kthyen. Ushtari vrapoi përpara tyre, u ngjit shkallëve, u shtri në shtrat dhe filloi të gërhiste. Kur princeshat kaluan pranë derës së tij, e dëgjuan dhe thanë: «Jemi të sigurta.» Hoqën fustanet, i vunë këpucët e grisura poshtë shtretërve dhe fjetën.$s$,
    $s$Në mëngjes, ushtari shkoi te mbreti. Princeshat qëndronin pas derës dhe dëgjonin. «Ku kërcejnë vajzat e mia natën?» pyeti mbreti. «Në një kështjellë nën tokë, me dymbëdhjetë princa», tha ushtari. Dhe tregoi gjithçka: për shkallët, për pemët e argjendta, të arta e prej diamanti, për liqenin e për barkat. Pastaj nxori tri degët. Princeshat e kuptuan që sekreti i tyre ishte zbuluar dhe pranuan gjithçka.$s$,
    $s$Mbreti e pyeti ushtarin cilën prej tyre donte për nuse. «Nuk jam më i ri», tha ushtari, «prandaj do të doja më të madhen, nëse ajo do.» Princesha më e madhe, që e kishte kuptuar sa i zgjuar e i durueshëm ishte, pranoi me buzëqeshje. Dasma u bë atë ditë, dhe në të kërcyen të gjithë, sepse ushtari tha: «Kërcimi s'ka asgjë të keqe. Vetëm sekretet duhet të kenë kufi.» Dhe që nga ajo ditë, princeshat kërcyen hapur, në sallën e pallatit, me derën hapur e me gjithë mbretërinë.$s$
  ]::text[],
  array['classic', 'adventure']::text[], 60, 120, 11, null,
  $s$<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 160 120"><defs><linearGradient id="gdymbedhjeteprincesha" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#1E3446"/><stop offset="1" stop-color="#2E5566"/></linearGradient></defs><rect x="0" y="0" width="160" height="120" fill="url(#gdymbedhjeteprincesha)"/><circle cx="104.9" cy="17.8" r="1.1" fill="#F3EBD9" opacity="0.7"/><circle cx="84.4" cy="16.3" r="0.9" fill="#F3EBD9" opacity="0.7"/><path d="M116.1 41Q116.1 43.9 119 43.9Q116.1 43.9 116.1 46.8Q116.1 43.9 113.19999999999999 43.9Q116.1 43.9 116.1 41Z" fill="#F3EBD9" opacity="0.9"/><circle cx="21" cy="12.3" r="1" fill="#F3EBD9" opacity="0.7"/><circle cx="136.8" cy="41" r="1.3" fill="#F3EBD9" opacity="0.7"/><circle cx="125.1" cy="22" r="11" fill="#F3EBD9"/><circle cx="119.1" cy="18" r="10" fill="#1E3446"/><path d="M0 83.5Q40 75.8 80 85.8T160 83V120H0Z" fill="#24455A"/><path d="M0 97.6Q40 92.1 80 100.1T160 97.8V120H0Z" fill="#1A3344"/><ellipse cx="80" cy="98" rx="30" ry="3" fill="#000000" opacity="0.08"/><g transform="translate(43 33) scale(1.15)"><rect x="6" y="22" width="12" height="38" rx="0" fill="#F3EBD9"/><rect x="46" y="22" width="12" height="38" rx="0" fill="#F3EBD9"/><rect x="18" y="32" width="28" height="28" rx="0" fill="#F3EBD9"/><path d="M4 22L12 8L20 22Z" fill="#E7B04B"/><path d="M44 22L52 8L60 22Z" fill="#E7B04B"/><path d="M12 8V0M52 8V0" fill="none" stroke="#F3EBD9" stroke-width="1" stroke-linecap="round" stroke-linejoin="round"/><path d="M12 0L18 2L12 4Z" fill="#E7B04B"/><path d="M52 0L58 2L52 4Z" fill="#E7B04B"/><path d="M26 60V48Q32 42 38 48V60Z" fill="#24455A"/><rect x="9" y="30" width="4" height="6" rx="2" fill="#24455A"/><rect x="49" y="30" width="4" height="6" rx="2" fill="#24455A"/><rect x="20" y="28" width="4" height="4" rx="0" fill="#F3EBD9"/><rect x="26" y="28" width="4" height="4" rx="0" fill="#F3EBD9"/><rect x="32" y="28" width="4" height="4" rx="0" fill="#F3EBD9"/><rect x="38" y="28" width="4" height="4" rx="0" fill="#F3EB