(
  $s$leo-meson-te-notoje$s$, 'sq', $s$Leo dhe deti i madh$s$,
  $s$Leo ka frikë nga deti, nga valët e nga uji që s'i sheh dot fundin. Babai nuk e nxiton. Hap pas hapi, ditë pas dite, Leo mëson se guximi rritet ngadalë.$s$,
  array[
    $s$Çdo verë, familja e Leos shkonte në det, në Dhërmi, në një shtëpi të vogël të bardhë me kanatat blu. Motra e madhe e Leos, Kejsi, vraponte në ujë sapo arrinin, duke bërtitur nga gëzimi. Babai notonte larg, deri te shkëmbi i madh. Edhe mamaja zhytej me syze nën ujë, për të parë peshqit. Por Leo rrinte në rërë.$s$,
    $s$Leo kishte frikë nga deti. Nuk ishte frikë e madhe, nga ato që të bëjnë të qash. Ishte një frikë e vogël, e qetë, që i rrinte në bark. Kishte frikë nga valët, që vinin njëra pas tjetrës dhe s'pushonin kurrë. Kishte frikë nga uji i thellë, ku s'shihej dot fundi. Dhe kishte frikë nga gjërat që mund të ishin nën ujë, që s'i shihte.$s$,
    $s$«Eja, Leo!» thërriste Kejsi nga uji. «Është shumë e ngrohtë!» Leo tundte kokën dhe vazhdonte të ndërtonte kështjellën e tij prej rëre, duke e kthyer shpinën nga deti. Por e shikonte me bisht të syrit, dhe ndjente diçka të çuditshme: donte të ishte edhe ai atje, por s'mundte.$s$,
    $s$Ditën e parë, babai erdhi dhe u ul pranë tij në rërë. Nuk i tha «Eja në ujë». I tha: «Ke ndërtuar një kështjellë të bukur. Por i duhet një hendek rreth e qark. Dhe hendekët mbushen me ujë deti. A më ndihmon të sjellim ujë me kovë?» Leo pranoi. Shkuan së bashku deri ku valët i lagnin rërën, mbushën kovën dhe u kthyen. Shumë herë. Dhe Leo, pa e kuptuar, i lagu këmbët në valë dhjetë herë.$s$,
    $s$Ditën e dytë, babai i tha: «Sot do të gjuajmë guaska. Ato më të bukurat janë pikërisht ku uji arrin deri te gjunjët.» Leo e mendoi pak. Pastaj e kapi babanë për dore dhe hyri në ujë, deri te gjunjët. Uji ishte i ngrohtë dhe i kthjellët. Shihte rërën poshtë, me guaska e me guralecë. Dhe pa një peshk të vogël, të tejdukshëm, që i kaloi pranë këmbës. Leo qeshi. «Më gudulisi!»$s$,
    $s$Ditën e tretë, erdhi një valë më e madhe se të tjerat dhe e lagu Leon deri në bark. Leo bërtiti dhe vrapoi në rërë, me zemrën që i rrihte fort. U ul në peshqir dhe s'deshi të hynte më. Babai erdhi, u ul pranë tij dhe s'e nxitoi. «Valët janë si qentë e mëdhenj», i tha. «Duken të frikshëm kur të vrapojnë drejt teje, por zakonisht duan vetëm të luajnë. Nuk ka gjë që u trembe. Ndonjëherë guximi bën një hap prapa para se të bëjë dy përpara.»$s$,
    $s$Ditën e katërt, Leo s'hyri në ujë. Vetëm rrinte në rërë dhe i shikonte valët. I shikonte gjatë. Pa që vinin në ritëm: një e vogël, një e vogël, një më e madhe. Pa që kur vinte vala e madhe, Kejsi kërcente lart, dhe vala i kalonte nën këmbë. Pa që uji i detit e mbante babanë mbi sipërfaqe, kur ai shtrihej me shpinë e me krahët e hapur, si një yll.$s$,
    $s$Ditën e pestë, Leo i tha babait: «Dua të provoj të kërcej mbi valë. Si Kejsi.» Babai e mori për dore dhe hynë në ujë deri te beli. Erdhi një valë e vogël. «Hop!» tha babai, dhe të dy kërcyen. Vala i kaloi poshtë. Erdhi një tjetër. «Hop!» Leo qeshi. Erdhi vala e madhe. Leo mbylli sytë. «Hop!» Dhe kërceu, dhe vala e ngriti pak, si një dorë e butë, dhe pastaj e uli. «E bëra!» thirri Leo.$s$,
    $s$Ditën e gjashtë, babai i tha: «A do të provosh të shtrihesh mbi ujë, si yll? Unë do të të mbaj me dorë poshtë shpinës.» Leo u shtri me kujdes, me kokën mbi ujë, me krahët e hapur. Ndjeu dorën e babait poshtë shpinës, të fortë e të sigurt. Ndjeu ujin që e mbante. Shikoi qiellin blu, pa një pulëbardhë që fluturonte. Dhe për herë të parë, deti nuk i dukej i frikshëm. I dukej si një shtrat i madh e i butë.$s$,
    $s$«Leo», tha babai me zë të ulët, «a e di që po rri mbi ujë vetëm?» Leo ktheu kokën. Babai kishte hequr dorën prej disa sekondash, dhe e mbante vetëm pranë, pa e prekur. Leo po notonte mbi ujë, vetë, si yll! Për një çast u tremb dhe u fundos pak, por babai e kapi menjëherë. Dhe Leo qeshi, duke pështyrë ujë të kripur. «Babi! Isha yll!»$s$,
    $s$Ditën e fundit të pushimeve, Leo hyri vetë në ujë, pa e kapur askush për dore. Jo shumë thellë, deri te beli. Kërceu mbi valë, u shtri si yll për pak sekonda, mblodhi guaska në fund. Kejsi e pa nga larg dhe thirri: «Shikoni Leon!» Dhe mamaja duartrokiti nga rëra, me syzet e diellit në kokë.$s$,
    $s$Atë mbrëmje, në ballkonin e shtëpisë së bardhë, ndërsa dielli zbriste në det, Leo u ul në prehrin e babait. «Babi», tha, «unë kam ende pak frikë nga deti.» «E di», tha babai. «Edhe unë kam pak. Deti është i madh, dhe duhet respektuar. Por ti sot hyre gjithsesi. Kjo është guximi. Jo të mos kesh frikë. Por të bësh hapin edhe kur ke pak frikë.»$s$,
    $s$Leo e shikoi detin, që ishte bërë portokalli e i qetë. Valët vinin butë në breg, një e vogël, një e vogël, një më e madhe. Dhe tani, i dukej sikur deti po merrte frymë, si ai. Atë natë, Leo ëndërroi që ishte një yll, që notonte mbi një det të madh e të ngrohtë, nën një qiell plot me yje të tjerë. Dhe nuk kishte fare frikë.$s$
  ]::text[],
  array['emotions', 'adventure']::text[], 36, 96, 12, 'boat',
  $s$<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 160 120"><defs><linearGradient id="gleomesontenotoje" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#C6E3EC"/><stop offset="1" stop-color="#EEF7F8"/></linearGradient></defs><rect x="0" y="0" width="160" height="120" fill="url(#gleomesontenotoje)"/><circle cx="29.1" cy="22" r="9" fill="#FFF3D6"/><path d="M42 34l4 3l4 -3M122.5 28l3 2.4l3 -2.4" fill="none" stroke="#5EA4B6" stroke-width="1.4" stroke-linecap="round" stroke-linejoin="round" opacity="0.7"/><rect x="0" y="76" width="160" height="44" rx="0" fill="#8CC3CF"/><path d="M0 86Q10 82 20 86T40 86T60 86T80 86T100 86T120 86T140 86T160 86" fill="none" stroke="#FFFFFF" stroke-width="1.2" stroke-linecap="round" stroke-linejoin="round" opacity="0.6"/><rect x="0" y="100" width="160" height="20" rx="0" fill="#5EA4B6"/><path d="M0 106Q10 102 20 106T40 106T60 106T80 106T100 106T120 106T140 106T160 106" fill="none" stroke="#FFFFFF" stroke-width="1.2" stroke-linecap="round" stroke-linejoin="round" opacity="0.5"/><ellipse cx="80" cy="98" rx="30" ry="3" fill="#000000" opacity="0.08"/><g transform="translate(43 33) scale(1.15)"><path d="M6 44H58L50 56H14Z" fill="#2A5263"/><path d="M32 44V6" fill="none" stroke="#2A5263" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/><path d="M34 8L56 40H34Z" fill="#E39A55"/><path d="M30 12L12 40H30Z" fill="#FFFFFF" opacity="0.9"/><path d="M0 60Q10 56 20 60T40 60T60 60" fill="none" stroke="#2A5263" stroke-width="1.4" stroke-linecap="round" stroke-linejoin="round" opacity="0.6"/></g></svg>$s$,
  'published', false, 700, 'editor'
),
(
  $s$aladini$s$, 'sq', $s$Aladini dhe llamba magjike$s$,
  $s$Nga «Një mijë e një netë»: një djalë i varfër gjen një llambë të vjetër, nga e cila del një xhind që plotëson dëshira. Por pasuria e vërtetë e Aladinit nuk është ajo që i jep llamba.$s$,
  array[
    $s$Në një qytet të largët, me kupola të arta e me tregje plot me erëza, jetonte një djalë i varfër që quhej Aladin. Babai i tij kishte vdekur, dhe nëna e tij tirrte pambuk që të mund të blinte bukë. Aladini ishte i mirë, por pak përtac, dhe kalonte ditët duke luajtur në rrugë.$s$,
    $s$Një ditë, iu afrua një burrë i huaj, me rroba të shtrenjta e me sy dinakë. Ishte një magjistar nga një vend i largët. «Unë jam xhaxhai yt», gënjeu ai, «vëllai i babait tënd. Dua të të ndihmoj të bëhesh i pasur.» Aladini, që s'e dinte se babai s'kishte pasur vëlla, e besoi dhe shkoi me të.$s$,
    $s$Magjistari e çoi jashtë qytetit, në një luginë të shkretë mes maleve. Ndezi një zjarr të vogël, hodhi pluhur në të dhe tha disa fjalë të çuditshme. Toka u drodh dhe u hap, dhe u shfaq një gur i madh me një unazë bronzi. «Poshtë këtij guri», tha magjistari, «është një shpellë plot me thesare. Vetëm ti mund të hysh. Mos prek asgjë, përveç një llambe të vjetër vaji në fund të shpellës. Ma sill mua.» Dhe i dha një unazë. «Kjo do të të mbrojë.»$s$,
    $s$Aladini zbriti në shpellë. Ishte e mrekullueshme: pemë me fruta prej xhevahiresh, rubinë të kuq si qershia, smeraldë të gjelbër si gjethe, perla të bardha si bora. Në fund, në një kamare, gjeti llambën: e vjetër, e nxirë, e thjeshtë. E mori dhe u kthye te dalja. «Ma jep llambën!» thirri magjistari nga lart. «Më ndihmo të dal më parë», tha Aladini. «Ma jep llambën!» bërtiti magjistari, dhe kur Aladini nuk ia dha, u zemërua aq shumë, sa e mbylli shpellën me gur.$s$,
    $s$Aladini mbeti në errësirë. U ul përtokë dhe, pa e ditur, fërkoi unazën që i kishte dhënë magjistari. Papritur, u shfaq një xhind i vogël. «Jam shërbëtori i unazës», tha. «Çfarë urdhëron?» «Më nxirr nga këtu!» tha Aladini. Dhe në një çast, ishte jashtë, në diell, me llambën në dorë.$s$,
    $s$Kur u kthye në shtëpi, nëna e tij tha: «Kjo llambë është shumë e ndotur. Do ta pastroj, dhe ndoshta mund ta shesim.» Dhe filloi ta fërkonte me një leckë. Papritur, nga llamba doli tym blu, gjithnjë e më shumë, dhe tymi u bë një xhind gjigant, me krahë të fortë e me sy si dy hëna. «Jam shërbëtori i llambës», tha me një zë që tundi muret. «Çfarë urdhëroni?»$s$,
    $s$Nëna e Aladinit u tremb aq shumë, sa ra pa ndjenja. Por Aladini e mori guximin. «Kemi uri», tha. «Na sill diçka për të ngrënë.» Dhe xhindi solli tryeza të mbushura me ushqime në pjata argjendi. Me kalimin e kohës, Aladini mësoi të përdorte llambën me mençuri. Nuk kërkonte shumë. Me argjendin e pjatave, ngriti një dyqan, mësoi të tregtonte, dhe u bë një djalë i ndershëm e i respektuar.$s$,
    $s$Një ditë, Aladini pa princeshën e qytetit, Badrul Budurin, ndërsa kalonte nëpër treg. Ishte e bukur, por ajo që i bëri më shumë përshtypje ishte se i fliste me mirësi një lypësi të varfër në rrugë. Aladini mendoi: «Ajo është si unë dikur.» Dhe u njohën, dhe u bënë miq, dhe pas pak kohësh u dashuruan. Aladini i kërkoi dorën. Sulltani pranoi, dhe me ndihmën e xhindit, Aladini ndërtoi një pallat të bukur përballë pallatit të sulltanit.$s$,
    $s$Por magjistari i ligë nuk e kishte harruar llambën. Kur dëgjoi për pallatin e mrekullueshëm, e kuptoi se Aladini ishte ende gjallë dhe kishte llambën. Erdhi në qytet, i veshur si tregtar, dhe thërriste nëpër rrugë: «Ndërroj llamba të vjetra me llamba të reja!» Princesha, që s'e dinte sekretin e llambës, i dha llambën e vjetër dhe mori një të re. Dhe magjistari e fërkoi menjëherë, dhe urdhëroi xhindin ta çonte gjithë pallatin, me princeshën brenda, në një vend shumë të largët.$s$,
    $s$Kur Aladini u kthye, pallati ishte zhdukur. Sulltani u zemërua dhe i dha dyzet ditë kohë për ta gjetur princeshën. Aladini fërkoi unazën. «A mund ta kthesh pallatin?» «Jo», tha xhindi i unazës. «Ajo është punë e xhindit të llambës. Por mund të të çoj atje.» Dhe e çoi në një qytet të largët, ku ishte pallati, dhe ku princesha rrinte e trishtuar te dritarja.$s$,
    $s$Princesha dhe Aladini bënë një plan. Atë mbrëmje, princesha e ftoi magjistarin në darkë dhe u bë sikur ishte gëzuar. I dha një pije me një pluhur gjumi që i kishte sjellë Aladini. Magjistari ra në gjumë të thellë. Aladini doli nga fshehtësira, mori llambën nga xhepi i magjistarit dhe e fërkoi. «Na kthe në shtëpi», i tha xhindit. «Me gjithë pallatin.» Dhe kështu u bë.$s$,
    $s$Magjistarin, xhindi e çoi në fund të shkretëtirës, aq larg sa s'u kthye më kurrë. Dhe Aladini, pasi u kthye, bëri diçka që askush s'e priste. Thirri xhindin dhe i tha: «Ke qenë shërbëtor për një mijë vjet. Sot je i lirë.» Xhindi e shikoi i habitur. Pastaj qeshi, një të qeshur të madhe si bubullimë e gëzuar, dhe u zhduk si tym blu, i lirë përgjithmonë.$s$,
    $s$Aladini dhe princesha jetuan të lumtur, dhe kur sulltani u plak, Aladini u bë një sundimtar i drejtë e i mirë. Nuk i duhej më llamba, sepse kishte mësuar se pasuria e vërtetë nuk vjen nga magjia. Vjen nga zemra e mirë, nga mendja e kthjellët dhe nga njerëzit që të duan. Dhe llamba e vjetër? E vendosën mbi dritare, ku ndizej çdo mbrëmje me vaj të zakonshëm, për të ndriçuar rrugën e atyre që vinin tek ata për ndihmë.$s$
  ]::text[],
  array['classic', 'adventure']::text[], 60, 132, 12, null,
  $s$<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 160 120"><defs><linearGradient id="galadini" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#1E3446"/><stop offset="1" stop-color="#2E5566"/></linearGradient></defs><rect x="0" y="0" width="160" height="120" fill="url(#galadini)"/><path d="M107.8 2.6999999999999997Q107.8 6.6 111.7 6.6Q107.8 6.6 107.8 10.5Q107.8 6.6 103.89999999999999 6.6Q107.8 6.6 107.8 2.6999999999999997Z" fill="#F3EBD9" opacity="0.9"/><circle cx="106.9" cy="17.4" r="0.9" fill="#F3EBD9" opacity="0.7"/><path d="M9.2 5.3Q9.2 9.1 13 9.1Q9.2 9.1 9.2 12.899999999999999Q9.2 9.1 5.3999999999999995 9.1Q9.2 9.1 9.2 5.3Z" fill="#F3EBD9" opacity="0.9"/><circle cx="117.8" cy="36.4" r="1.5" fill="#F3EBD9" opacity="0.7"/><path d="M42.5 24.4Q42.5 27.7 45.8 27.7Q42.5 27.7 42.5 31Q42.5 27.7 39.2 27.7Q42.5 27.7 42.5 24.4Z" fill="#F3EBD9" opacity="0.9"/><circle cx="148.1" cy="24.1" r="1.2" fill="#F3EBD9" opacity="0.7"/><circle cx="121.8" cy="22" r="11" fill="#F3EBD9"/><circle cx="115.8" cy="18" r="10" fill="#1E3446"/><path d="M0 87.8Q40 80.3 80 90.3T160 86.1V120H0Z" fill="#24455A"/><path d="M0 98.6Q40 89.9 80 97.9T160 96.6V120H0Z" fill="#1A3344"/><ellipse cx="80" cy="98" rx="30" ry="3" fill="#000000" opacity="0.08"/><g transform="translate(43 33) scale(1.15)"><path d="M6 44Q8 34 22 34H44Q56 32 60 26L62 28Q58 40 46 44Z" fill="#E7B04B"/><ellipse cx="30" cy="34" rx="10" ry="4" fill="#E7B04B"/><circle cx="30" cy="30" r="3" fill="#E7B04B"/><path d="M8 40Q0 36 4 30" fill="none" stroke="#E7B04B" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"/><rect x="20" y="44" width="22" height="4" rx="2" fill="#E7B04B"/><path d="M60 24Q56 14 62 8Q58 2 62 -4" fill="none" stroke="#F3EBD9" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" opacity="0.5"/><circle cx="61" cy="24" r="2.4" fill="#D9644A" opacity="0.8"/></g></svg>$s$,
