),
(
  $s$qyteti-me-nje-mije-dritare$s$, 'sq', $s$Qyteti me një mijë dritare$s$,
  $s$Maca Mia shëtit mbi çatitë e Beratit kur bie nata, dhe pas çdo dritareje gjen një familje që po përgatitet për gjumë.$s$,
  array[
    $s$Në Berat, qytetin me një mijë dritare, shtëpitë janë ngjitur njëra mbi tjetrën në shpatin e kodrës, si librat në një raft të madh. Dhe kur bie mbrëmja, dritaret ndizen një nga një, derisa i gjithë qyteti duket si një qiell me yje.$s$,
    $s$Mbi këto çati jetonte një mace e vogël gri, me çorape të bardha në këmbë. Quhej Mia. Çdo mbrëmje, para se të shkonte në shtëpi, Mia bënte një shëtitje të vogël mbi çatitë me tjegulla, ngadalë, pa zhurmë, me bishtin lart si një pikëpyetje. Donte t'u uronte natën e mirë të gjithë dritareve.$s$,
    $s$Te dritarja e parë, poshtë pranë lumit, banonte furrtari. Ai po vinte brumin në magje për bukën e mëngjesit dhe e mbulonte me një peshqir të bardhë. «Fli, brumë», i pëshpëriste. «Fli e rritu, se nesër do të jesh bukë e ngrohtë.» Mia mbylli sytë dhe nuhati erën e mirë të miellit. «Natën e mirë, furrtar», mjaulliti butë.$s$,
    $s$Te dritarja e dytë, një gjysh me syze lexonte gazetën pranë një llambe të verdhë. Në gjunjët e tij flinte një qen i vogël kafe, që gërhiste lehtë. Gjyshi e palosi gazetën, e fiku llambën dhe i tha qenit: «Hajde, mik, se u bë vonë.» «Natën e mirë, gjysh», mjaulliti Mia.$s$,
    $s$Te dritarja e tretë, dy binjakë me pizhame me yje po lanin dhëmbët përpara pasqyrës. Bënin shkumë të bardhë dhe qeshnin, sepse dukeshin si plakë me mjekër. Mamaja i thirri nga dhoma: «Shpejt, se po ju pret libri!» Binjakët vrapuan, u futën nën jorgan dhe dritarja u mbush me dritë të butë leximi. «Natën e mirë, binjakë», mjaulliti Mia.$s$,
    $s$Te dritarja e katërt, një nënë e re tundte një djep të vogël druri. Brenda flinte një foshnjë, me grushtet e vogla pranë faqeve. Nëna këndonte ngadalë një ninullë të vjetër: «Nina, nina, bir i nënës, rritu si lisi i malit.» Mia nuk mjaulliu fare atje. Vetëm uli kokën dhe vazhdoi rrugën me hapa edhe më të lehtë, që të mos e zgjonte foshnjën.$s$,
    $s$Te dritarja e pestë, një piktore po lante penelat në një gotë me ujë. Mbi kavalet kishte një pikturë të pambaruar: ishte pikërisht qyteti i Beratit natën, me një mijë dritare të ndezura. Dhe në një cep të pikturës, mbi një çati, ishte vizatuar një mace e vogël gri. Mia u ndal dhe e vështroi gjatë. «Kjo jam unë?» pyeti me vete, dhe i rrahu bishti nga gëzimi.$s$,
    $s$Te dritarja e gjashtë, një vajzë e vogël ishte ulur në krevat dhe s'po flinte. Shikonte nga dritarja, nga hëna që ishte ngjitur mbi kalanë. Babai i saj erdhi, u ul pranë saj dhe i tregoi yjet me gisht: «Ai është Ylli i Karvanit. Ai është Arusha e Madhe. Dhe ai, i vogli atje, je ti.» Vajza qeshi, u shtri dhe mbylli sytë.$s$,
    $s$Ndërkohë, dritaret e Beratit po fikeshin një nga një. Ajo e furrtarit. Ajo e gjyshit. Ajo e binjakëve. Ajo e piktores. Qyteti po zhytej ngadalë në gjumë, dhe vetëm hëna, mbi kala, mbetej zgjuar për t'i ruajtur të gjithë.$s$,
    $s$Mia u ngjit në çatinë e fundit, në krye të kodrës, aty ku ishte shtëpia e saj. Dritarja ishte ende e ndezur. Brenda, një djalë i vogël, Andi, e priste ulur në prag, me një tas me qumësht pranë. «Ku ishe, Mia?» i tha. «Të prita.»$s$,
    $s$Mia hyri nga dritarja e hapur, piu pak qumësht dhe u hodh në krevatin e Andit. U rrotullua tri herë, siç bëjnë macet, dhe u kruspullos te këmbët e tij si një lëmsh i ngrohtë gri. Andi fiku dritën. Tani edhe dritarja e tyre u errësua, dhe Berati, qyteti me një mijë dritare, flinte i tëri.$s$,
    $s$Natën e mirë, furrtar. Natën e mirë, gjysh. Natën e mirë, binjakë dhe foshnjë e vogël. Natën e mirë, Mia. Natën e mirë, ti.$s$
  ]::text[],
  array['sleep']::text[], 0, 72, 8, null,
  $s$<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 160 120"><defs><linearGradient id="gqytetimenjemijedrita" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#1E3446"/><stop offset="1" stop-color="#2E5566"/></linearGradient></defs><rect x="0" y="0" width="160" height="120" fill="url(#gqytetimenjemijedrita)"/><path d="M65.2 8.5Q65.2 12.1 68.8 12.1Q65.2 12.1 65.2 15.7Q65.2 12.1 61.6 12.1Q65.2 12.1 65.2 8.5Z" fill="#F3EBD9" opacity="0.9"/><circle cx="120.6" cy="25.1" r="1" fill="#F3EBD9" opacity="0.7"/><circle cx="143.4" cy="19.8" r="1" fill="#F3EBD9" opacity="0.7"/><path d="M128.9 25.700000000000003Q128.9 29.1 132.3 29.1Q128.9 29.1 128.9 32.5Q128.9 29.1 125.5 29.1Q128.9 29.1 128.9 25.700000000000003Z" fill="#F3EBD9" opacity="0.9"/><circle cx="150.4" cy="20.4" r="0.8" fill="#F3EBD9" opacity="0.7"/><path d="M118.2 17Q118.2 19.4 120.60000000000001 19.4Q118.2 19.4 118.2 21.799999999999997Q118.2 19.4 115.8 19.4Q118.2 19.4 118.2 17Z" fill="#F3EBD9" opacity="0.9"/><circle cx="114.4" cy="32.4" r="1.3" fill="#F3EBD9" opacity="0.7"/><circle cx="31.4" cy="22" r="11" fill="#F3EBD9"/><circle cx="37.4" cy="18" r="10" fill="#1E3446"/><path d="M0 86.8Q40 74.4 80 84.4T160 88.8V120H0Z" fill="#24455A"/><path d="M0 96.5Q40 90.2 80 98.2T160 97.5V120H0Z" fill="#1A3344"/><ellipse cx="80" cy="98" rx="30" ry="3" fill="#000000" opacity="0.08"/><g transform="translate(43 33) scale(1.15)"><path d="M2 60V34L12 24L22 34V60Z" fill="#F3EBD9"/><path d="M22 60V26L34 14L46 26V60Z" fill="#F3EBD9"/><path d="M46 60V38L54 30L62 38V60Z" fill="#F3EBD9"/><rect x="8" y="38" width="4" height="5" rx="1" fill="#E7B04B"/><rect x="28" y="30" width="5" height="6" rx="1" fill="#E7B04B"/><rect x="35" y="42" width="5" height="6" rx="1" fill="#E7B04B"/><rect x="52" y="44" width="4" height="5" rx="1" fill="#E7B04B"/><rect x="30" y="50" width="8" height="10" rx="1" fill="#24455A"/></g></svg>$s$,
  'published', false, 720, 'editor'
),
(
  $s$mami-kthehet-gjithmone$s$, 'sq', $s$Mami kthehet gjithmonë$s$,
  $s$Mamaja e Elsës fillon punë, dhe Elsa kalon ditët me gjyshen. Ora e madhe e kuzhinës i tregon kur do të kthehet mamaja, dhe dita mbushet me gjëra të vogla për t'i treguar.$s$,
  array[
    $s$Mamaja e Elsës kishte qëndruar në shtëpi me të gjithë kohën, që kur Elsa kishte lindur. Por tani Elsa ishte dy vjeç e gjysmë, dhe mamaja duhej të kthehej në punë. «Nga e hëna», i tha mamaja, «unë do të shkoj në punë në mëngjes, dhe ti do të rrish me gjyshen Dava. Dhe në pasdite, unë do të kthehem.»$s$,
    $s$Elsa nuk e kuptoi shumë mirë. Por të hënën në mëngjes, kur mamaja veshi pallton dhe mori çantën, Elsa e kuptoi. U kap pas këmbës së mamasë dhe filloi të qante. «Mos ik, mami! Mos ik!» Mamaja u ul në gjunjë dhe e përqafoi. «Unë po shkoj, zemër, por do të kthehem. Mami kthehet gjithmonë.»$s$,
    $s$Gjyshja Dava e mori Elsën në krahë. Mamaja i dha një puthje në faqe, një në ballë dhe një në majë të hundës, dhe doli nga dera. Elsa qau në krahët e gjyshes, me kokën mbi supin e saj. Gjyshja nuk i tha «Mos qaj». E mbajti fort, e lëkundi pak, dhe i tha: «Të mungon mamaja. E kuptoj. Edhe mua më mungon kur ikën.»$s$,
    $s$Kur Elsa u qetësua pak, gjyshja e çoi në kuzhinë dhe i tregoi orën e madhe të murit, me shigjeta të zeza e me numra të mëdhenj. «Shiko», i tha. «Kjo shigjeta e vogël, tani është te numri tetë. Kur ajo të shkojë deri te numri pesë, këtu poshtë, mamaja do të kthehet. Do ta shikojmë bashkë si ecën.»$s$,
    $s$Elsa e shikoi orën gjatë. Shigjeta e vogël nuk po lëvizte fare. «S'po ecën», tha. Gjyshja qeshi. «Ecën shumë ngadalë, si breshka. Por nëse bëjmë gjëra të bukura, ajo ecën më shpejt. A do të bëjmë petulla për mëngjes?» Elsa tundi kokën. Dhe bënë petulla, me miell që u përhap gjithandej, me vezë që Elsa i theu vetë, dhe me mjaltë sipër.$s$,
    $s$Pas mëngjesit, Elsa shikoi orën. Shigjeta e vogël kishte shkuar te numri nëntë! «Ka ecur!» thirri. «Po», tha gjyshja. «Tani le të dalim në park.» Në park, Elsa ushqeu pëllumbat me thërrime buke, u rrëshqit në rrëshqitësen e vogël dhjetë herë, dhe gjeti një gjethe të madhe të kuqe, në formë dore. «Kjo është për mamin», tha, dhe e futi në xhep.$s$,
    $s$Kur u kthyen në shtëpi, shigjeta e vogël ishte te numri dymbëdhjetë, në majë të orës. «Gjysmë rruge», tha gjyshja. Hëngrën drekë: supë pule me makarona të vogla si yje. Pastaj Elsa bëri gjumin e drekës, në shtratin e saj, me ariun e saj. Kur u zgjua, vrapoi në kuzhinë. Shigjeta e vogël ishte te numri tre!$s$,
    $s$«Edhe pak!» tha Elsa. «Çfarë do t'i tregosh mamasë kur të kthehet?» pyeti gjyshja. Elsa u mendua. «Petullat. Pëllumbat. Rrëshqitësen. Gjethen.» «Po të bëjmë edhe një vizatim për të?» Dhe Elsa vizatoi me ngjyra: një rreth të madh të verdhë që ishte dielli, një vijë të gjatë që ishte mamaja, dhe një vijë të shkurtër pranë saj që ishte Elsa. Dhe shumë zemra të kuqe përreth.$s$,
    $s$Shigjeta e vogël erdhi te numri katër. Elsa u ul te dritarja, me vizatimin në duar e me gjethen e kuqe pranë, dhe shikonte rrugën. Gjyshja u ul pranë saj. «Edhe pak», tha. Elsa numëronte makinat që kalonin. Një makinë e kuqe. Një autobus. Një biçikletë. Një qen me një zonjë.$s$,
    $s$Shigjeta e vogël u afrua te numri pesë. Dhe pastaj, në fund të rrugës, Elsa pa një pallto të njohur, një çantë të njohur dhe një flok të njohur që lëkundej në erë. «MAMI!» thirri, aq fort sa u dëgjua deri në fund të rrugës. Vrapoi te dera, dhe kur dera u hap, u hodh në krahët e mamasë.$s$,
    $s$«Të thashë që do të kthehesha», tha mamaja, duke e përqafuar fort, shumë fort. «Mami kthehet gjithmonë.» Elsa i dha vizatimin dhe gjethen e kuqe. Dhe pastaj i tregoi gjithçka: petullat, pëllumbat, rrëshqitësen, orën që ecte si breshkë. Mamaja e dëgjoi me vëmendje, duke e mbajtur në prehër. «Paske pasur një ditë të mrekullueshme», tha. «Dhe unë mendova për ty gjithë ditën.»$s$,
    $s$Ditët e tjera ishin më të lehta. Elsa qau pak edhe të martën, pak më pak të mërkurën, dhe të enjten vetëm tha: «Mirupafshim, mami! Kthehu kur shigjeta të jetë te pesë!» Dhe çdo ditë, kishte diçka të re për t'i treguar mamasë kur kthehej. Një gjethe, një gur, një vizatim, një këngë.$s$,
    $s$Sonte, para gjumit, mamaja i tha Elsës: «Nesër do të shkoj përsëri në punë.» «E di», tha Elsa, me sytë gjysmë të mbyllur. «Dhe do të kthehesh kur shigjeta të jetë te pesë.» «Pikërisht.» «Sepse mami kthehet gjithmonë», pëshpëriti Elsa. Dhe e zuri gjumi, e sigurt dhe e qetë, me dorën e mamasë në dorën e saj.$s$
  ]::text[],
  array['emotions']::text[], 0, 60, 10, null,
  $s$<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 160 120"><defs><linearGradient id="gmamikthehetgjithmone" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#F0E0CE"/><stop offset="1" stop-color="#F8EEE3"/></linearGradient></defs><rect x="0" y="0" width="160" height="120" fill="url(#gmamikthehetgjithmone)"/><rect x="14" y="14" width="34" height="40" rx="3" fill="#2E5566"/><path d="M24 23Q24 26 27 26Q24 26 24 29Q24 26 21 26Q24 26 24 23Z" fill="#F3EBD9"/><circle cx="38" cy="24" r="5" fill="#F3EBD9"/><path d="M31 14V54M14 34H48" fill="none" stroke="#F0E0CE" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"/><rect x="124" y="22" width="18" height="14" rx="1.5" fill="#E7D2BC"/><rect x="127" y="25" width="12" height="8" rx="1" fill="#A6CDB4"/><rect x="0" y="92" width="160" height="28" rx="0" fill="#DCC3A8"/><ellipse cx="80" cy="104" rx="50" ry="8" fill="#E7D2BC"/><ellipse cx="80" cy="98" rx="30" ry="3" fill="#000000" opacity="0.08"/><g transform="translate(43 35) scale(1.15)"><circle cx="32" cy="30" r="22" fill="#7A4E3A"/><circle cx="32" cy="30" r="18" fill="#F8EEE3"/><path d="M32 30V16M32 30L42 34" fill="none" stroke="#7A4E3A" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"/><circle cx="32" cy="30" r="2" fill="#7A4E3A"/><rect x="31" y="13" width="2" height="4" rx="1" fill="#7A4E3A" transform="rotate(0 32 30)"/><rect x="31" y="13" width="2" height="4" rx="1" fill="#7A4E3A" transform="rotate(90 32 30)"/><rect x="31" y="13" width="2" height="4" rx="1" fill="#7A4E3A" transform="rotate(180 32 30)"/><rect x="31" y="13" width="2" height="4" rx="1" fill="#7A4E3A" transform="rotate(270 32 30)"/><path d="M32 52V60" fill="none" stroke="#7A4E3A" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></g></svg>$s$,
  'published', false, 730, 'editor'
),
(
  $s$androkli-dhe-luani$s$, 'sq', $s$Androkli dhe luani$s$,
  $s$Fabul e vjetër, e treguar nga Ezopi: një njeri i ikur i heq një gjemb nga putra një luani në shpellë. Vite më vonë, luani e njeh.$s$,
  array[
    $s$Shumë kohë më parë, në kohën e Romës së vjetër, jetonte një njeri që quhej Androkli. Ishte skllav i një zotërie të pasur e të ashpër, që e bënte të punonte nga mëngjesi deri në mbrëmje dhe s'i jepte kurrë pushim. Një natë, Androkli nuk duroi më. Iku nga shtëpia e zotërisë dhe vrapoi drejt pyllit e maleve, sa më larg që mundi.$s$,
    $s$Eci për shumë ditë, i uritur e i etur. Fshihej ditën dhe ecte natën, që të mos e gjenin ushtarët që e kërkonin. Më në fund, i lodhur e i dobësuar, arriti te një shpellë në shpatin e një mali. Hyri brenda për t'u fshehur nga dielli i nxehtë dhe ra përtokë, i rraskapitur.$s$,
    $s$Por pak më vonë, dëgjoi një zë që i ngriu gjakun: një ulërimë e thellë e e fortë. Hyrja e shpellës u errësua, dhe brenda hyri një luan i madh, me jele të verdha e të ngatërruara. Androkli u mbështet pas murit të shpellës, i bindur se kishte ardhur fundi i tij.$s$,
    $s$Por luani nuk u hodh mbi të. Ecte me vështirësi, duke çaluar, dhe ulërinte jo nga zemërimi, por nga dhimbja. U ul përtokë dhe ngriti njërën putër të përparme, duke e lëpirë e duke rënkuar. Pastaj e vështroi Androklin me sy të lodhur, sikur t'i kërkonte ndihmë.$s$,
    $s$Androkli e kuptoi. Mblodhi gjithë guximin që kishte dhe u afrua ngadalë. Luani nuk lëvizi. Androkli u ul në gjunjë dhe pa putrën e madhe: në mes të saj kishte ngulur një gjemb të madh e të mprehtë, dhe rreth tij ishte fryrë e skuqur. «Mos lëviz, mik», pëshpëriti Androkli. «Do të të dhembë pak, por pastaj do të të kalojë.»$s$,
    $s$E kapi gjembin me gishta dhe e tërhoqi me kujdes. Luani lëshoi një ulërimë të shkurtër, por nuk e lëvizi putrën. Gjembi doli. Androkli e pastroi plagën me ujë nga një burim pranë shpellës dhe e lidhi me një copë nga këmisha e tij. Luani e shikoi gjatë, pastaj i lëpiu dorën, si një qen që falënderon të zotin, dhe u shtri pranë tij.$s$,
    $s$Që atë ditë, Androkli dhe luani u bënë miq. Jetuan bashkë në shpellë për shumë muaj. Luani gjuante dhe i sillte Androklit pjesën më të mirë. Androkli i krehte jelet me gishta dhe i fliste natën, kur yjet dukeshin nga hyrja e shpellës. Luani e dëgjonte me kokën mbi putra.$s$,
    $s$Por një ditë, ndërsa luani ishte larg për gjah, ushtarët e gjetën Androklin. E lidhën dhe e çuan në Romë. Ligji i atyre kohëve ishte i ashpër me skllevërit që iknin, dhe e dënuan që të futej në arenën e madhe, para një luani të uritur, që njerëzit ta shihnin si spektakël.$s$,
    $s$Ditën e caktuar, arena ishte plot me mijëra njerëz. Edhe perandori ishte i ulur në vendin e tij të nderit. Androklin e futën në mes të arenës, vetëm, pa armë. Pastaj u hap një portë e madhe, dhe prej saj doli me vrap një luan i madh, i uritur, që ulërinte e tundte bishtin. Turma bërtiti.$s$,
    $s$Luani vrapoi drejt Androklit. Por kur ishte vetëm disa hapa larg, ndaloi papritur. Nuhati ajrin. E vështroi. Pastaj, para syve të habitur të gjithë arenës, iu afrua ngadalë, uli kokën, i fërkoi jelet pas këmbëve dhe filloi t'i lëpinte duart, si një mace e madhe që gëzohet. Ishte luani i shpellës. E kishin kapur edhe atë.$s$,
    $s$Androkli e njohu menjëherë dhe e përqafoi rreth qafës, duke qarë nga gëzimi. Arena u shndërrua në heshtje. Askush s'kishte parë kurrë diçka të tillë. Perandori thirri Androklin përpara vetes dhe i kërkoi t'i tregonte si ishte e mundur.$s$,
    $s$Androkli i tregoi gjithë historinë: për ikjen, për shpellën, për gjembin dhe për muajt që kishin kaluar bashkë. Perandori e dëgjoi me vëmendje, dhe kur Androkli mbaroi, u ngrit në këmbë. «Ky njeri ka treguar mëshirë ndaj një kafshe të egër», tha me zë të lartë, «dhe kafsha i ka treguar mirënjohje. A mund të jemi ne, njerëzit, më pak të mirë se një luan?»$s$,
    $s$Perandori i fali lirinë Androklit. Dhe i fali lirinë edhe luanit. Thonë se për shumë vite, njerëzit e Romës shihnin një burrë të qetë që ecte nëpër rrugët e qytetit, me një luan të madh e të butë që i ecte pranë, pa zinxhir. Dhe kur dikush i pyeste si mund të ishin miq, Androkli thoshte: «Mirësia nuk harrohet kurrë. As nga njerëzit, as nga luanët.»$s$
  ]::text[],
  array['classic', 'friendship']::text[], 48, 120, 10, null,
  $s$<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 160 120"><defs><linearGradient id="gandroklidheluani" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#BBDAE4"/><stop offset="1" stop-color="#EAF4F2"/></linearGradient></defs><rect x="0" y="0" width="160" height="120" fill="url(#gandroklidheluani)"/><circle cx="123.1" cy="22" r="10" fill="#FFF3D6"/><ellipse cx="34" cy="26" rx="14" ry="5" fill="#FFFFFF" opacity="0.85"/><circle cx="30" cy="22" r="6" fill="#FFFFFF" opacity="0.85"/><circle cx="39" cy="21" r="5" fill="#FFFFFF" opacity="0.85"/><path d="M0 87.3Q40 79.6 80 91.6T160 82.7V120H0Z" fill="#A6CDB4"/><path d="M0 97.8Q40 89.1 80 97.1T160 100.3V120H0Z" fill="#86B897"/><ellipse cx="80" cy="98" rx="30" ry="3" fill="#000000" opacity="0.08"/><g transform="translate(43 33) scale(1.15)"><ellipse cx="24" cy="44" rx="18" ry="10" fill="#35504B"/><circle cx="46" cy="30" r="15" fill="#E07B5F"/><circle cx="46" cy="30" r="9.5" fill="#35504B"/><circle cx="42.5" cy="28" r="1.3" fill="#EAF4F2"/><circle cx="49.5" cy="28" r="1.3" fill="#EAF4F2"/><ellipse cx="46" cy="33" rx="3" ry="2" fill="#EAF4F2" opacity="0.6"/><rect x="10" y="48" width="6" height="12" rx="3" fill="#35504B"/><rect x="28" y="48" width="6" height="12" rx="3" fill="#35504B"/><path d="M6 42Q0 48 4 54" fill="none" stroke="#35504B" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/><circle cx="4" cy="55" r="2.6" fill="#E07B5F"/></g></svg>$s$,
  'published', false, 740, 'editor'
),
(
  $s$miu-dhe-luani$s$, 'sq', $s$Miu dhe luani$s$,
  $s$Sipas Ezopit: luani e lë të lirë një mi të vogël që e zgjoi nga gjumi, dhe qesh kur miu i premton se një ditë do ta ndihmojë. Por një ditë, vjen pikërisht ajo ditë.$s$,
  array[
    $s$Në savanën e madhe, ku bari është i verdhë si ari dhe pemët kanë formën e çadrave, jetonte një luan i madh. Ishte mbreti i kafshëve. Kur ulërinte, zogjtë fluturonin nga pemët dhe zebrat ngrinin kokat. Por luani ishte edhe dembel, dhe pasditeve, kur dielli digjte, flinte gjatë nën hijen e një akacieje.$s$,
    $s$Pranë asaj akacieje, në një vrimë mes rrënjëve, jetonte një mi i vogël kafe. Ishte aq i vogël, sa mund të ulej në një gjethe, dhe aq i shpejtë, sa askush s'e kapte dot. Një pasdite, miu doli nga vrima për të kërkuar fara. Ishte aq i zënë duke nuhatur barin, sa nuk vuri re ku po shkonte, dhe vrapoi drejt e mbi hundën e luanit që flinte.$s$,
    $s$Luani u zgjua me një teshtimë. Hapi sytë, pa miun e vogël mbi hundë dhe me një lëvizje të shpejtë e zuri me putrën e tij të madhe. «Kush guxon të më zgjojë?» ulëriu. Miu u drodh i tëri nën putër, me zemrën që i rrihte si daulle e vogël.$s$,
    $s$«Më fal, o mbret!» thirri miu. «Nuk e bëra me dashje! Të lutem, më lër të shkoj. Nëse më fal sot, të premtoj që një ditë do të të ndihmoj edhe unë.» Luani e vështroi për një çast, pastaj filloi të qeshte, aq shumë sa iu tund gjithë jelja. «Ti? Të më ndihmosh mua? Një mi i vockël të ndihmojë mbretin e kafshëve? Kjo është shakaja më e mirë që kam dëgjuar sot!»$s$,
    $s$Por ndoshta sepse kishte qeshur kaq shumë, ose sepse s'kishte uri, luani e ngriti putrën. «Shko, mi i vogël», tha, duke fshirë një lot nga e qeshura. «Ma zbukurove ditën. Shko, para se të ndërroj mendje.» Miu nuk e humbi kohën. Vrapoi drejt vrimës së tij dhe nga pragu thirri: «Faleminderit, o mbret! Nuk do ta harroj!» Luani tundi kokën dhe u kthye në gjumë.$s$,
    $s$Kaluan disa javë. Një mëngjes, gjahtarët erdhën në savanë. Kishin ardhur për të kapur një luan për kopshtin zoologjik të një qyteti të largët. Ngritën një rrjetë të madhe prej litarësh të trashë në shtegun ku luani shkonte çdo ditë për të pirë ujë, dhe u fshehën pas shkurreve.$s$,
    $s$Kur luani kaloi, rrjeta ra mbi të. U përpoq të çlirohej, por sa më shumë lëvizte, aq më shumë i ngatërroheshin litarët rreth trupit. U kafshua, u përpëlit, u hodh majtas e djathtas, por rrjeta ishte e fortë. Më në fund, i lodhur, ulëriu me gjithë fuqinë, një ulërimë që u dëgjua deri në fund të savanës.$s$,
    $s$Miu i vogël po hante fara pranë akacies kur e dëgjoi atë ulërimë. E njohu menjëherë. «Ky është luani!» tha. «Është në hall!» Dhe pa e menduar dy herë, vrapoi me sa i hanin këmbët e vogla, mbi gurë e nëpër bar, drejt zërit.$s$,
    $s$Kur arriti, pa luanin e madh, të lidhur në rrjetë, që s'lëvizte dot. Sytë e luanit ishin të trishtuar. «Mos u tremb, o mbret», tha miu. «Erdha.» Luani e vështroi. «Ti? Çfarë mund të bësh ti? Gjahtarët do të kthehen së shpejti.» «Ki durim», tha miu. «Do ta shohësh.»$s$,
    $s$Miu u ngjit mbi rrjetë dhe filloi të brente litarët me dhëmbët e tij të vegjël e të mprehtë. Kafshonte e kafshonte, krr-krr-krr, një litar, pastaj tjetrin. Ishte punë e gjatë, se litarët ishin të trashë, dhe dhëmbët e miut ishin të vegjël. Por miu nuk ndalej. Kafshonte pa pushim, edhe kur i dhembnin dhëmbët, edhe kur dielli i digjte shpinën.$s$,
    $s$Pas një kohe të gjatë, litari i fundit u këput. Rrjeta u hap. Luani doli, shkundi jelet dhe u shtri në bar, i lirë. Pastaj ktheu kokën e madhe nga miu i vogël, që ishte ulur i rraskapitur mbi një gur, me gjuhën jashtë. «Kur më the që do të më ndihmoje», tha luani me zë të ulët, «unë qesha. Më fal, mik. Sot më shpëtove jetën.»$s$,
    $s$«S'ka gjë», tha miu, duke fshirë djersën nga mustaqet. «Ti më fale një herë. Unë të fala sot. Kështu bëjnë miqtë.» Luani e uli kokën deri në tokë, që miu të mund t'i hipte mbi hundë, këtë herë me leje. Dhe të dy u kthyen bashkë drejt akacies, para se të ktheheshin gjahtarët.$s$,
    $s$Që nga ajo ditë, luani dhe miu u bënë miqtë më të mirë të savanës. Luani mbronte miun nga gjarpërinjtë e nga zogjtë grabitqarë. Dhe miu, çdo mbrëmje, i tregonte luanit lajmet e ditës, të gjitha gjërat e vogla që një luan i madh s'i sheh. Dhe luani mësoi diçka që s'e harroi kurrë: askush nuk është shumë i vogël për të qenë mik i vërtetë.$s$
  ]::text[],
  array['classic', 'friendship']::text[], 0, 84, 10, 'mice',
  $s$<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 160 120"><defs><linearGradient id="gmiudheluani" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#BBDAE4"/><stop offset="1" stop-color="#EAF4F2"/></linearGradient></defs><rect x="0" y="0" width="160" height="120" fill="url(#gmiudheluani)"/><circle cx="37.3" cy="22" r="10" fill="#FFF3D6"/><ellipse cx="118" cy="26" rx="14" ry="5" fill="#FFFFFF" opacity="0.85"/><circle cx="114" cy="22" r="6" fill="#FFFFFF" opacity="0.85"/><circle cx="123" cy="21" r="5" fill="#FFFFFF" opacity="0.85"/><path d="M0 90.7Q40 74.6 80 86.6T160 91.3V120H0Z" fill="#A6CDB4"/><path d="M0 98.7Q40 94.5 80 102.5T160 97.5V120H0Z" fill="#86B897"/><ellipse cx="80" cy="98" rx="30" ry="3" fill="#000000" opacity="0.08"/><g transform="translate(43 33) scale(1.15)"><ellipse cx="32" cy="50" rx="13" ry="9" fill="#35504B"/><path d="M42 46L54 50L42 55Z" fill="#35504B"/><circle cx="41" cy="41" r="6" fill="#35504B"/><circle cx="41" cy="41" r="3" fill="#E07B5F" opacity="0.8"/><circle cx="48" cy="48" r="1.2" fill="#EAF4F2"/><circle cx="54" cy="50" r="1.2" fill="#E07B5F"/><path d="M19 52Q4 50 6 40Q8 34 14 36" fill="none" stroke="#35504B" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></g></svg>$s$,
  'published', false, 750, 'editor'
),
(
  $s$arushi-i-humbur$s$, 'sq', $s$Ku humbi Pufi?$s$,
  $s$Para gjumit, Joni s'e gjen arushin e tij, Pufin. Me mamanë, kthehen pas në gjithë ditën, vend pas vendi, për ta gjetur.$s$,
  array[
    $s$Ishte koha e gjumit. Joni kishte larë dhëmbët, kishte veshur pizhamat me raketa dhe ishte futur në shtrat. Por diçka mungonte. Kërkoi nën jastëk. Kërkoi nën jorgan. Kërkoi pranë murit. «Mami!» thirri. «Ku është Pufi?»$s$,
    $s$Pufi ishte arushi i Jonit. Ishte i vogël, kafe, me një vesh pak të qepur, se një herë ia kishte kafshuar qeni i gjyshit, dhe me një hundë të zezë që ishte zbardhur pak nga puthjet. Joni s'kishte fjetur kurrë pa Pufin. As një natë të vetme.$s$,
    $s$Mamaja erdhi dhe kërkoi edhe ajo: nën shtrat, në dollap, në koshin e lodrave. Pufi nuk ishte askund. Joni filloi të qante. «Pa Pufin s'mund të fle!» Mamaja u ul pranë tij dhe i fshiu lotët. «Do ta gjejmë», tha. «Por duhet ta kujtojmë gjithë ditën, prapa, si detektivë. Ku ishte Pufi për herë të fundit?»$s$,
    $s$Joni u mendua. «Sonte në banjë», tha. «Ishte në buzë të vaskës, që të shikonte rosat.» Shkuan në banjë. Rosat e verdha ishin aty, në buzë të vaskës. Por Pufi jo. «Hmm», tha mamaja. «Po para banjës?»$s$,
    $s$«Para banjës hëngrëm darkë», tha Joni. «Pufi ishte ulur në karrigen pranë meje. I dhashë pak makarona, me mend.» Shkuan në kuzhinë. Karrigia ishte bosh, vetëm me disa thërrime. Kontrolluan nën tryezë: një lugë, një pecetë, një kokërr bizele. Por Pufi jo.$s$,
    $s$«Po para darkës?» «Para darkës luajtëm në oborr me babin», tha Joni. «Pufi ishte në kamionin e madh, në pjesën prapa, si shofer.» Mamaja ndezi dritën e oborrit dhe dolën të dy, me pantofla, në ajrin e freskët të mbrëmjes. Kamioni i madh i verdhë ishte pranë kopshtit me lule. Por në pjesën prapa kishte vetëm gurë e një gjethe. Pufi jo.$s$,
    $s$Joni filloi të shqetësohej përsëri. «Po sikur ta ketë marrë dikush? Po sikur të ketë ikur?» «Arushët nuk ikin», tha mamaja. «Ata presin gjithmonë aty ku i lëmë. Le të kujtojmë më shumë. Para oborrit?»$s$,
    $s$«Para oborrit shkuam te gjyshja», tha Joni ngadalë. «Dhe Pufi... Pufi ishte në makinë, në karrigen e vogël pranë meje. Dhe kur zbritëm... nuk e mbaj mend.» Mamaja mori çelësat e makinës. Dolën përsëri, në oborr, deri te makina e parkuar. Mamaja e hapi derën e pasme dhe ndezi dritën e brendshme.$s$,
    $s$Dhe atje, në dysheme, mes karriges së vogël dhe derës, i rënë me kokëposhtë, ishte Pufi! Ishte pak i pluhurosur, me një gjethe në vesh, por ishte ai. Joni e kapi dhe e përqafoi aq fort, sa mamaja qeshi. «E gjete!» «E gjetëm», tha Joni. «Bashkë. Si detektivë.»$s$,
    $s$Kur u kthyen në dhomë, mamaja e pastroi Pufin me një leckë të lagur, i hoqi gjethen nga veshi dhe ia dha Jonit. Joni u fut nën jorgan me Pufin nën mjekër. «Pufi i gjorë», tha. «Ka qenë vetëm në makinë, në errësirë. Duhet të ketë pasur frikë.»$s$,
    $s$«Ndoshta», tha mamaja. «Por ndoshta jo shumë. Sepse e dinte që ti do ta kërkoje. Kur e di që dikush të do, edhe kur je vetëm, s'ke shumë frikë.» Joni e mendoi këtë. Pastaj e shikoi Pufin në sy, dy sytë e tij të vegjël prej kopsash. «Të kërkova në gjithë shtëpinë», i tha. «Dhe do të të kërkoj gjithmonë.»$s$,
    $s$Mamaja i dha një puthje Jonit, një Pufit, dhe fiku dritën. «Natën e mirë, detektivë», tha. Joni qeshi pak. Pastaj u kthye në krah, me Pufin e ngrohtë në krahë, me hundën e zbardhur pranë faqes. Dhe e zuri gjumi menjëherë, sikur i gjithë kërkimi ta kishte lodhur shumë.$s$,
    $s$Që nga ajo natë, para se të zbriste nga makina, Joni pyeste gjithmonë: «A e kam Pufin?» Dhe mamaja buzëqeshte. Sepse kishte mësuar që gjërat e çmuara s'humbasin kurrë vërtet. Duhet vetëm të kthehesh pas, me durim, dhe t'i kërkosh aty ku i ke lënë.$s$
  ]::text[],
  array['emotions', 'sleep']::text[], 0, 60, 8, 'bear',
  $s$<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 160 120"><defs><linearGradient id="garushiihumbur" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#F0E0CE"/><stop offset="1" stop-color="#F8EEE3"/></linearGradient></defs><rect x="0" y="0" width="160" height="120" fill="url(#garushiihumbur)"/><rect x="112" y="14" width="34" height="40" rx="3" fill="#2E5566"/><path d="M122 23Q122 26 125 26Q122 26 122 29Q122 26 119 26Q122 26 122 23Z" fill="#F3EBD9"/><circle cx="136" cy="24" r="5" fill="#F3EBD9"/><path d="M129 14V54M112 34H146" fill="none" stroke="#F0E0CE" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"/><rect x="18" y="22" width="18" height="14" rx="1.5" fill="#E7D2BC"/><rect x="21" y="25" width="12" height="8" rx="1" fill="#A6CDB4"/><rect x="0" y="92" width="160" height="28" rx="0" fill="#DCC3A8"/><ellipse cx="80" cy="104" rx="50" ry="8" fill="#E7D2BC"/><ellipse cx="80" cy="98" rx="30" ry="3" fill="#000000" opacity="0.08"/><g transform="translate(43 35) scale(1.15)"><ellipse cx="28" cy="40" rx="20" ry="14" fill="#7A4E3A"/><circle cx="48" cy="28" r="10" fill="#7A4E3A"/><circle cx="42" cy="19" r="4" fill="#7A4E3A"/><circle cx="54" cy="19" r="4" fill="#7A4E3A"/><circle cx="42" cy="19" r="1.8" fill="#F8EEE3" opacity="0.6"/><circle cx="54" cy="19" r="1.8" fill="#F8EEE3" opacity="0.6"/><ellipse cx="56" cy="31" rx="5.5" ry="4" fill="#7A4E3A"/><circle cx="60" cy="30" r="1.8" fill="#F8EEE3"/><path d="M49 25.5q2 1.6 4 0" fill="none" stroke="#F8EEE3" stroke-width="1.2" stroke-linecap="round" stroke-linejoin="round"/><rect x="12" y="44" width="8" height="16" rx="4" fill="#7A4E3A"/><rect x="34" y="44" width="8" height="16" rx="4" fill="#7A4E3A"/></g></svg>$s$,
  'published', false, 760, 'editor'
),
(
  $s$pelikani-pelo$s$, 'sq', $s$Pelikani Pelo i Karavastasë$s$,
  $s$Pelo, një pelikan i vogël kaçurrel në lagunën e Divjakës, mendon se sqepi i tij i madh është qesharak, derisa një natë me stuhi zbulon për çfarë i shërben.$s$,
  array[
    $s$Në bregun e Adriatikut, ku pyjet e pishave takojnë detin, është një lagunë e madhe dhe e qetë që quhet Karavasta. Uji i saj është i cekët dhe i kripur, dhe mbi të shtrihen ishuj të vegjël me kallama. Aty, çdo pranverë, vijnë të bëjnë folenë pelikanët kaçurrelë, zogjtë më të mëdhenj të gjithë vendit.$s$,
    $s$Në një nga ata ishuj lindi Pelo. Ishte një pelikan i vogël gri, me pupla të ngatërruara mbi kokë, si të sapozgjuar, dhe me një sqep aq të gjatë sa i dukej se mbante një lugë gjigante. Poshtë sqepit kishte një qese lëkure, që lëkundej sa herë që ecte.$s$,
    $s$Pranë tij, në cektinat e lagunës, jetonin flamingot. Ishin rozë, të hollë e të gjatë, dhe ecnin në ujë sikur kërcenin balet. Pelo i shikonte me zili. «Ato janë kaq të bukura», i tha një ditë gjyshit të tij. «Ndërsa unë kam këtë sqep të madh e këtë qese qesharake. Flamingot qeshin kur më shohin.»$s$,
    $s$Gjyshi pelikan, që kishte parë shumë pranvera, e vështroi me qetësi. «Çdo zog ka diçka që i duhet», tha. «Flamingoja ka këmbë të gjata për të ecur në ujë. Ti ke një sqep që është si rrjetë peshkatari. Një ditë do ta kuptosh vetë.»$s$,
    $s$Pelo provoi të peshkonte, por në fillim i shkonte keq. Fuste kokën në ujë dhe nxirrte vetëm baltë. Ose hapte qesen aq shumë, sa uji e mbushte dhe s'mund ta ngrinte dot kokën. Flamingot i qeshnin nga larg, me zëra të hollë, si bori të vogla. Pelo ulte kokën dhe notonte drejt kallamave.$s$,
    $s$Por gjyshi s'e linte të dorëzohej. «Ngadalë», i thoshte. «Hape qesen kur peshqit janë afër, pastaj mbylle sqepin dhe ngrije kokën që uji të dalë anash. Peshqit mbeten brenda.» Pelo provoi njëherë, dy herë, dhjetë herë. Dhe një mëngjes, kur ngriti kokën, ndjeu diçka që lëvizte në qese. Ishin tre peshq të vegjël argjendi. Pelo u gëzua aq shumë, sa i hapi krahët dhe pothuajse u rrëzua në ujë.$s$,
    $s$Ditët kalonin dhe Pelo bëhej gjithnjë e më i zoti. Mësoi edhe të fluturonte, në fillim me vështirësi, pastaj gjithnjë e më lart, duke rrotulluar mbi lagunë me krahët e mëdhenj të hapur, si një qilim i bardhë që lëviz në erë.$s$,
    $s$Një mbrëmje vere, nga deti u ngrit një stuhi e papritur. Era frynte aq fort sa përkulte kallamat deri në ujë, dhe valët e lagunës, zakonisht të qeta, u bënë të egra e të shkumëzuara. Zogjtë fluturuan të gjithë drejt ishujve për t'u strehuar.$s$,
    $s$Ndërsa po ngutej drejt folesë, Pelo dëgjoi një zë të hollë që qante. Në mes të ujit, mbi një copë dru që lëkundej, ishte një flamingo e vogël, ende gri, se flamingot e vogla nuk janë rozë kur lindin. Kishte humbur nënën në stuhi dhe dridhej e tëra.$s$,
    $s$Pelo nuk e mendoi dy herë. Notoi drejt saj, kundër valëve, dhe kur arriti pranë, hapi krahun e madh dhe e mbuloi si me një çadër. «Mos ki frikë», i tha. «Hyr nën krahun tim. Unë jam i madh, dhe era s'më lëviz dot.» Flamingoja e vogël u strehua nën puplat e tij të ngrohta, dhe Pelo e shtyu ngadalë copën e drurit drejt ishullit të kallamave.$s$,
    $s$Gjithë natën stuhia uluriti mbi lagunë, por Pelo nuk lëvizi. Mbante flamingon e vogël nën krah dhe i këndonte me zërin e tij të ngjirur të vetmen këngë që dinte, atë që i kishte kënduar gjyshi kur ishte i vogël. Dhe flamingoja e vogël, më në fund, e zuri gjumi.$s$,
    $s$Në mëngjes, kur stuhia kaloi dhe dielli doli mbi pisha, nëna flamingo erdhi duke fluturuar e duke thirrur. Kur pa të voglin e saj të gjallë e të ngrohtë nën krahun e Pelos, u përkul para tij me qafën e saj të gjatë rozë. Edhe flamingot e tjera u afruan. Asnjëra nuk qeshte më.$s$,
    $s$«Të qeshëm me sqepin tënd», tha nëna flamingo, «por ti ke krahët më të mëdhenj dhe zemrën më të madhe të lagunës.» Pelo u skuq, aq sa mund të skuqet një pelikan, dhe nuk dinte ç'të thoshte.$s$,
    $s$Nga ajo ditë, flamingoja e vogël e ndiqte Pelon kudo. Ai e mësoi të mos kishte frikë nga valët, dhe ajo e mësoi të ecte në një këmbë. Dhe kur dikush i thoshte se ishte i çuditshëm, Pelo hapte krahët e mëdhenj dhe kujtonte fjalët e gjyshit: çdo zog ka diçka që i duhet. Edhe ti, edhe unë.$s$
  ]::text[],
  array['nature', 'friendship']::text[], 0, 84, 10, null,
  $s$<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 160 120"><defs><linearGradient id="gpelikanipelo" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#C6E3EC"/><stop offset="1" stop-color="#EEF7F8"/></linearGradient></defs><rect x="0" y="0" width="160" height="120" fill="url(#gpelikanipelo)"/><circle cx="27.5" cy="22" r="9" fill="#FFF3D6"/><path d="M39.3 34l4 3l4 -3M122.4 28l3 2.4l3 -2.4" fill="none" stroke="#5EA4B6" stroke-width="1.4" stroke-linecap="round" stroke-linejoin="round" opacity="0.7"/><rect x="0" y="76" width="160" height="44" rx="0" fill="#8CC3CF"/><path d="M0 86Q10 82 20 86T40 86T60 86T80 86T100 86T120 86T140 86T160 86" fill="none" stroke="#FFFFFF" stroke-width="1.2" stroke-linecap="round" stroke-linejoin="round" opacity="0.6"/><rect x="0" y="100" width="160" height="20" rx="0" fill="#5EA4B6"/><path d="M0 106Q10 102 20 106T40 106T60 106T80 106T100 106T120 106T140 106T160 106" fill="none" stroke="#FFFFFF" stroke-width="1.2" stroke-linecap="round" stroke-linejoin="round" opacity="0.5"/><ellipse cx="80" cy="98" rx="30" ry="3" fill="#000000" opacity="0.08"/><g transform="translate(43 33) scale(1.15)"><ellipse cx="28" cy="40" rx="17" ry="11" fill="#2A5263"/><path d="M12 40L2 44L12 46Z" fill="#2A5263"/><path d="M40 34Q48 26 44 17" fill="none" stroke="#2A5263" stroke-width="6" stroke-linecap="round" stroke-linejoin="round"/><circle cx="44" cy="16" r="5.5" fill="#2A5263"/><path d="M48 15L63 21Q57 30 46 23Z" fill="#E39A55"/><circle cx="45" cy="14" r="1.2" fill="#EEF7F8"/><path d="M24 50L24 56M32 50L32 56" fill="none" stroke="#E39A55" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/><path d="M4 58Q16 55 28 58T56 58" fill="none" stroke="#EEF7F8" stroke-width="1.4" stroke-linecap="round" stroke-linejoin="round" opacity="0.6"/></g></svg>$s$,
  'published', false, 770, 'editor'
),
(
  $s$milingona-dhe-gjinkalla$s$, 'sq', $s$Milingona dhe gjinkalla$s$,
  $s$Sipas Ezopit, e treguar butë: gjinkalla këndon gjithë verën, milingona punon. Kur vjen dimri, milingona ka diçka për t'i dhënë gjinkallës, dhe gjinkalla diçka për t'i dhënë milingonës.$s$,
  array[
    $s$Ishte verë, dhe fusha ishte plot me diell. Gruri ishte i verdhë, lulekuqet ishin të kuqe, dhe ajri dridhej nga vapa. Në një degë ulliri, ulur në diell, një gjinkallë këndonte gjithë ditën: cri-cri-cri, cri-cri-cri. Këndonte për diellin, për qiellin blu, për erën e lehtë. Dhe ishte e lumtur.$s$,
    $s$Poshtë, në tokë, një milingonë e vogël punonte pa pushim. Mblidhte kokrra gruri që binin nga kallinjtë, një nga një, dhe i mbante në shpinë deri te foleja e saj nën tokë. Kokrrat ishin më të mëdha se ajo, por milingona nuk ankohej. Shkonte e vinte, shkonte e vinte, nga mëngjesi deri në mbrëmje.$s$,
    $s$«Hej, milingonë!» i thirri gjinkalla nga dega. «Pse lodhesh kaq shumë në këtë vapë? Eja të këndojmë bashkë! Shiko sa ditë e bukur është!» Milingona ndaloi për një çast dhe fshiu djersën. «Po mbledh ushqim për dimrin», tha. «Dimri vjen, dhe atëherë s'do të ketë më as grurë, as fruta. Duhet të përgatitemi tani.»$s$,
    $s$Gjinkalla qeshi. «Dimri? Ç'dimër? Shiko përreth: ka ushqim kudo! Ka kohë për dimrin.» Dhe vazhdoi të këndonte: cri-cri-cri. Milingona tundi kokën dhe vazhdoi punën, me një kokërr gruri në shpinë.$s$,
    $s$Kaloi korriku. Kaloi gushti. Gjinkalla këndonte, milingona punonte. Pastaj erdhi shtatori, dhe ditët filluan të shkurtoheshin. Erdhi tetori, dhe gjethet u zverdhën. Erdhi nëntori, me shi të ftohtë e me erë. Gjinkalla nuk këndonte më aq shpesh. Dhe pastaj, një mëngjes dhjetori, ra bora e parë.$s$,
    $s$Fusha ishte e bardhë, e heshtur dhe e ftohtë. Nuk kishte më grurë, as lule, as fruta. Gjinkalla dridhej nën një gjethe të thatë. Kishte uri, kishte ftohtë dhe s'kishte ku të shkonte. Atëherë kujtoi milingonën. Me hapa të ngadaltë e me krahët e ngrirë, shkoi deri te foleja e saj dhe trokiti në derën e vogël.$s$,
    $s$Milingona doli, e ngrohtë e me një shall të vogël rreth qafës. «Milingonë», tha gjinkalla me zë të dobët, «kam uri e kam ftohtë. Gjithë verën këndova dhe nuk mendova për dimrin. Kishe të drejtë. A mund të më japësh pak ushqim?»$s$,
    $s$Milingona e vështroi gjatë. Mund t'i thoshte: «Gjithë verën këndove? Atëherë tani vallëzo!» Kështu thuhet në përrallën e vjetër. Por milingona kishte zemër të mirë. Dhe kujtoi edhe diçka tjetër: gjithë verën, ndërsa ajo punonte nën diell, kënga e gjinkallës e kishte shoqëruar. Kur ishte e lodhur, kënga i jepte forcë. Kur ishte e vetmuar, kënga i bënte shoqëri.$s$,
    $s$«Hyr», tha milingona. «Kam grurë të mjaftueshëm për të dyja.» Gjinkalla hyri në folenë e ngrohtë nën tokë, ku kishte dhoma plot me kokrra gruri, fara e thërrime buke. Milingona i dha të hante dhe e vendosi pranë zjarrit. Dhe gjinkalla, kur u ngroh pak, tha: «Si mund të të shpërblej? Unë s'kam asgjë.»$s$,
    $s$«Ke diçka», tha milingona. «Këngën tënde. Netët e dimrit janë të gjata dhe të errëta këtu poshtë. Milingonat e mia janë të lodhura e të mërzitura. Na këndo.» Dhe gjinkalla këndoi. Këndoi për diellin e verës, për lulekuqet, për qiellin blu. Dhe milingonat, që s'e kishin dëgjuar kurrë një këngë nga afër, u mblodhën rreth saj dhe e dëgjuan të mahnitura.$s$,
    $s$Gjithë dimrin, gjinkalla jetoi me milingonat. Çdo mbrëmje këndonte, dhe milingonat harronin të ftohtin jashtë. Dhe gjinkalla mësoi nga milingonat se si ruhet ushqimi, si përgatitesh për ditët e vështira, si punohet bashkë.$s$,
    $s$Kur erdhi pranvera, gjinkalla doli përsëri në diell. Por kësaj radhe, kur këndonte nga dega e ullirit, këndonte vetëm mbrëmjeve. Ditën, ndihmonte milingonat të mblidhnin fara. «Kënga është e bukur», tha, «por edhe puna. Dhe të dyja janë më të bukura kur i ndan me miqtë.»$s$,
    $s$Dhe kështu, në atë fushë, që nga ai vit, puna dhe kënga shkuan së bashku. Milingonat punonin me këngë, gjinkalla këndonte me bark të ngopur, dhe askush nuk kaloi më dimër të vetmuar.$s$
  ]::text[],
  array['classic', 'lessons', 'friendship']::text[], 0, 84, 8, null,
  $s$<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 160 120"><defs><linearGradient id="gmilingonadhegjinkall" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#D3E8CB"/><stop offset="1" stop-color="#F4F7EA"/></linearGradient></defs><rect x="0" y="0" width="160" height="120" fill="url(#gmilingonadhegjinkall)"/><circle cx="120.8" cy="22" r="10" fill="#FFF3D6"/><ellipse cx="34" cy="26" rx="14" ry="5" fill="#FFFFFF" opacity="0.85"/><circle cx="30" cy="22" r="6" fill="#FFFFFF" opacity="0.85"/><circle cx="39" cy="21" r="5" fill="#FFFFFF" opacity="0.85"/><path d="M0 86.2Q40 75.7 80 87.7T160 83.2V120H0Z" fill="#B5D39A"/><path d="M0 96.5Q40 92.2 80 100.2T160 99.5V120H0Z" fill="#93BE7B"/><circle cx="23.1" cy="109.1" r="1.6" fill="#FFFFFF" opacity="0.9"/><circle cx="116.2" cy="109.2" r="1.6" fill="#E7B04B" opacity="0.9"/><circle cx="145.9" cy="104.5" r="1.6" fill="#E7B04B" opacity="0.9"/><circle cx="27.2" cy="107.7" r="1.6" fill="#E58C8A" opacity="0.9"/><circle cx="47.4" cy="111.4" r="1.6" fill="#FFFFFF" opacity="0.9"/><circle cx="148.1" cy="109.1" r="1.6" fill="#E58C8A" opacity="0.9"/><circle cx="30.7" cy="106" r="1.6" fill="#FFFFFF" opacity="0.9"/><ellipse cx="80" cy="98" rx="30" ry="3" fill="#000000" opacity="0.08"/><g transform="translate(43 33) scale(1.15)"><circle cx="16" cy="46" r="7" fill="#3E5A38"/><circle cx="29" cy="46" r="5" fill="#3E5A38"/><circle cx="41" cy="42" r="6.5" fill="#3E5A38"/><path d="M44 37Q48 28 54 28M41 36Q42 28 48 24M20 52L14 60M29 51L29 60M34 50L40 60M24 50L22 60" fill="none" stroke="#3E5A38" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"/><circle cx="43" cy="40" r="1" fill="#F4F7EA"/></g></svg>$s$,
  'published', false, 780, 'editor'
),
(
  $s$ngjyrat-e-ndjenjave$s$, 'sq', $s$Ngjyrat e ndjenjave$s$,
  $s$Piktori i vogël Rei vizaton ndjenjat e tij me ngjyra: i verdhë kur është i gëzuar, blu kur është i trishtuar, i kuq kur zemërohet. Por një ditë ndjen të gjitha njëkohësisht.$s$,
  array[
    $s$Rei ishte gjashtë vjeç dhe i pëlqente të vizatonte më shumë se çdo gjë tjetër. Kishte një kuti të madhe me ngjyra, me njëzet e katër lapsa të mprehur, dhe një bllok të trashë me fletë të bardha. Vizatonte kudo: në tryezë, në dysheme, në makinë, edhe në banjë, kur mamaja s'e shihte.$s$,
    $s$Gjyshja e Reit i kishte mësuar një lojë. «Kur s'di si ndihesh», i kishte thënë, «zgjidh një ngjyrë. Ngjyrat dinë shumë gjëra për ndjenjat.» Dhe Rei kishte zbuluar që kjo ishte e vërtetë.$s$,
    $s$Kur ishte i gëzuar, kur dilte në park ose kur vinte babai nga puna, Rei zgjidhte gjithmonë të verdhën. Vizatonte diej të mëdhenj, lule luledielli, zogj që fluturonin. E verdha i dukej si një e qeshur. E ngrohtë e e ndritshme.$s$,
    $s$Kur ishte i trishtuar, kur shoku i tij i ngushtë u transferua në një qytet tjetër ose kur i vdiq peshku i kuq, Rei zgjidhte blunë. Vizatonte shi, dete të mëdhenj, një hënë të vetmuar. Blu i dukej si lotët. E ftohtë, por edhe e butë, si një përqafim i qetë.$s$,
    $s$Kur ishte i zemëruar, kur motra i prishte vizatimet ose kur s'e linin të rrinte zgjuar, Rei zgjidhte të kuqen. Shtypte lapsin aq fort, sa ndonjëherë thyhej maja. Vizatonte vija të shpejta, zigzag, vullkane që shpërthenin. E kuqja i dukej si një britmë.$s$,
    $s$Kur kishte frikë, Rei zgjidhte vjollcën e errët. Kur ishte i qetë, zgjidhte jeshilen, si bari i një livadhi. Kur ishte i habitur, portokallinë, si një fishekzjarr. Dhe kur ishte i dashuruar me diçka, si me qenin e fqinjit, rozën. Çdo ndjenjë kishte ngjyrën e saj, dhe Rei e njihte secilën.$s$,
    $s$Por një ditë, ndodhi diçka e çuditshme. Ishte dita e ditëlindjes së tij të gjashtë, dhe Rei ishte i gëzuar: kishte tortë me çokollatë, kishte shokë, kishte dhurata. Por gjyshja s'kishte ardhur, sepse ishte sëmurë, dhe kjo e bënte të trishtuar. Dhe kur kushëriri i tij i hapi një dhuratë para tij, pa e pyetur, Rei u zemërua. Dhe pastaj, kur fiku qirinjtë, pati pak frikë nga flakët. Gjithçka në të njëjtën ditë.$s$,
    $s$Atë mbrëmje, Rei u ul me bllokun e tij dhe donte të vizatonte ditën. Por s'dinte cilën ngjyrë të zgjidhte. Mori të verdhën, pastaj e la. Mori blunë, pastaj e la. Mori të kuqen. Mori vjollcën. S'mund të zgjidhte. «Nuk funksionon», tha i mërzitur. «Nuk e di si ndihem.»$s$,
    $s$Mamaja u ul pranë tij. «Çfarë ndodh?» Rei i shpjegoi. «Sot isha i gëzuar, por edhe i trishtuar, edhe i zemëruar, edhe pak i frikësuar. Nuk ka një ngjyrë për të gjitha bashkë.» Mamaja buzëqeshi. «Po pse duhet të zgjedhësh vetëm një?» i tha. «A s'mund t'i përdorësh të gjitha?»$s$,
    $s$Rei e shikoi mamanë i habitur. Pastaj, ngadalë, mori të verdhën dhe vizatoi një diell të madh në mes të fletës, dhe tortën me qirinj. Pastaj mori blunë dhe vizatoi një re të vogël në qoshe, me pak shi, për gjyshen që s'kishte ardhur. Mori të kuqen dhe vizatoi një vijë të vogël zigzag pranë dhuratës. Mori vjollcën dhe vizatoi flakët e qirinjve. Dhe në fund, mori rozën dhe vizatoi zemra rreth e qark, për të gjithë shokët që kishin ardhur.$s$,
    $s$Kur mbaroi, e shikoi vizatimin. Ishte vizatimi më i çuditshëm që kishte bërë ndonjëherë. Kishte diell e shi në të njëjtën kohë. Kishte zemra e zigzag. Por ishte i bukur. Ishte, mendoi Rei, si një ylber. Dhe ylberi del pikërisht kur ka edhe diell edhe shi.$s$,
    $s$«Shiko», i tha mamaja. «Dita jote ishte si ylber. Me shumë ngjyra. Dhe kjo është normale. Ndonjëherë ndjejmë shumë gjëra njëkohësisht. Edhe të rriturit. Nuk ka asgjë të gabuar. Thjesht do të thotë që ke një zemër të madhe, me shumë ngjyra brenda.»$s$,
    $s$Të nesërmen, Rei shkoi me mamanë te gjyshja, që ishte ende në shtrat, dhe i dha vizatimin. Gjyshja e shikoi gjatë. «Sa vizatim i bukur», tha. «Po kjo re e vogël me shi?» «Ajo jam unë që më mungove», tha Rei. Gjyshja e përqafoi fort. Dhe Rei ndjeu që brenda tij, tani, ishte vetëm një ngjyrë: e verdha, e ngrohtë e e ndritshme. Por e dinte që nesër mund të ishin përsëri shumë, dhe kjo ishte në rregull.$s$
  ]::text[],
  array['emotions']::text[], 36, 96, 9, null,
  $s$<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 160 120"><defs><linearGradient id="gngjyratendjenjave" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#F0E0CE"/><stop offset="1" stop-color="#F8EEE3"/></linearGradient></defs><rect x="0" y="0" width="160" height="120" fill="url(#gngjyratendjenjave)"/><rect x="14" y="14" width="34" height="40" rx="3" fill="#2E5566"/><path d="M24 23Q24 26 27 26Q24 26 24 29Q24 26 21 26Q24 26 24 23Z" fill="#F3EBD9"/><circle cx="38" cy="24" r="5" fill="#F3EBD9"/><path d="M31 14V54M14 34H48" fill="none" stroke="#F0E0CE" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"/><rect x="124" y="22" width="18" height="14" rx="1.5" fill="#E7D2BC"/><rect x="127" y="25" width="12" height="8" rx="1" fill="#A6CDB4"/><rect x="0" y="92" width="160" height="28" rx="0" fill="#DCC3A8"/><ellipse cx="80" cy="104" rx="50" ry="8" fill="#E7D2BC"/><ellipse cx="80" cy="98" rx="30" ry="3" fill="#000000" opacity="0.08"/><g transform="translate(43 35) scale(1.15)"><path d="M10 54Q24 40 34 46Q44 52 56 38" fill="none" stroke="#D9644A" stroke-width="6" stroke-linecap="round" stroke-linejoin="round" opacity="0.85"/><rect x="36" y="2" width="6" height="34" rx="3" fill="#8A5A44" transform="rotate(30 39 19)"/><path d="M24 40L30 30L36 34L30 44Z" fill="#E7B04B"/></g></svg>$s$,
  'published', false, 790, 'editor'
),
(
  $s$bariu-qe-therriste-ujku$s$, 'sq', $s$Djali që thërriste «Ujku!»$s$,
  $s$Sipas Ezopit: një bari i ri mërzitet dhe gënjen fshatarët se ka ardhur ujku. Kur ujku vjen vërtet, askush s'i beson më.$s$,
  array[
    $s$Në një fshat të vogël rrëzë malit, jetonte një djalë që quhej Petrit. Babai i tij ishte bari, por ishte sëmurë, prandaj Petriti duhej të nxirrte vetë dhentë e familjes në kullotë, lart në kodër, mbi fshat. Fshatarët i kishin thënë: «Nëse vjen ujku, thirr fort, dhe ne do të vijmë menjëherë me shkopinj për ta përzënë.»$s$,
    $s$Ditët në kodër ishin të gjata. Petriti numëronte retë, numëronte dhentë, numëronte gurët. I fliste qenit, por qeni flinte. Fyell nuk dinte t'i binte. Dhe një pasdite, i mërzitur si kurrë më parë, i lindi një ide. «Po të thërras sikur ka ardhur ujku», mendoi, «do të shoh si vrapojnë të gjithë. Do të jetë qesharake.»$s$,
    $s$Ngriti duart rreth gojës dhe bërtiti me sa fuqi kishte: «Ujku! Ujku! Erdhi ujku! Ndihmë!» Poshtë në fshat, njerëzit e lanë punën. Bujku la parmendën, furrtari la brumin, gratë lanë rrobat. Të gjithë morën shkopinj e sfurqe dhe vrapuan lart në kodër, të djersitur e me frymë të prerë.$s$,
    $s$Kur arritën, gjetën dhentë që kullotnin të qeta dhe Petritin që po qeshte aq shumë, sa ishte shtrirë në bar. «Ku është ujku?» pyetën. «S'ka ujk!» tha Petriti, duke qeshur. «Bëra shaka! Duhej ta shihnit si vrapuat!» Fshatarët u shikuan me njëri-tjetrin. Nuk qeshën. «Mos e bëj më këtë», tha plaku i fshatit. Dhe u kthyen në punët e tyre, të lodhur e të nevrikosur.$s$,
    $s$Kaluan disa ditë. Petriti u mërzit përsëri. Dhe kujtoi sa i kishte qeshur atë herë. «Edhe një herë», mendoi. «Vetëm edhe një herë.» Dhe bërtiti: «Ujku! Ujku! Ndihmë! Erdhi ujku!» Fshatarët dëgjuan, dhe disa thanë: «Prapë po bën shaka.» Por të tjerët thanë: «Po sikur këtë herë të jetë e vërtetë?» Dhe vrapuan përsëri lart në kodër.$s$,
    $s$Dhe përsëri, gjetën dhentë të qeta dhe Petritin që qeshte. Këtë herë, fshatarët u zemëruan vërtet. «Ti po luan me ne», tha plaku i fshatit. «Por një ditë, kur të kesh vërtet nevojë, askush s'do të të besojë më.» Petriti ngriti supet. Mendoi se plaku po e teprotte.$s$,
    $s$Kaloi një javë. Një mbrëmje, kur dielli po perëndonte dhe hijet e pemëve ishin bërë të gjata, Petriti dëgjoi një zhurmë në pyllin pas kodrës. Pa një hije gri që lëvizte mes shkurreve. Pastaj dy sy të verdhë. Ishte ujku. Ujk i vërtetë, i madh e i uritur, që po afrohej ngadalë drejt deleve.$s$,
    $s$Petriti u tremb aq shumë, sa iu prenë këmbët. Pastaj bërtiti, më fort se kurrë: «Ujku! Ujku! Ujku i vërtetë! Ju lutem, ndihmë!» Poshtë në fshat, fshatarët e dëgjuan. Por tundën kokat. «Prapë ai djalë me shakatë e tij», thanë. «S'do të na gënjejë më.» Dhe askush nuk u ngrit.$s$,
    $s$Petriti thirri e thirri, deri sa iu ngjir zëri. Ujku u hodh drejt tufës. Dhentë u trembën dhe ikën në të gjitha drejtimet, duke blegëritur, nëpër shkurre e poshtë nëpër shpat. Qeni lehu dhe vrapoi pas ujkut, dhe ujku, i ndjekur nga qeni, u kthye në pyll. Por kur zhurma pushoi, dhentë kishin ikur kudo, të shpërndara nëpër mal, në errësirë.$s$,
    $s$Petriti zbriti në fshat duke qarë. Kur fshatarët e panë pa dhentë, me lot në sy e me rroba të grisura, e kuptuan që këtë herë s'kishte qenë shaka. Babai i Petritit doli nga shtëpia, i sëmurë, i mbështetur te shkopi. Petriti u hodh në krahët e tij. «Më fal», qau. «Gënjeva dy herë, dhe tani që thashë të vërtetën, askush s'më besoi.»$s$,
    $s$Babai e përqafoi. «Kjo është gjëja më e rëndë që mund të humbësh», i tha butë. «Jo dhentë. Besimin e njerëzve. Dhentë mund t'i gjejmë. Besimin, duhet ta fitosh përsëri, ngadalë, ditë pas dite.»$s$,
    $s$Fshatarët, kur dëgjuan, ndezën pishtarë dhe dolën të gjithë bashkë në mal. Kërkuan gjithë natën, dhe një nga një, i gjetën dhentë: të fshehura pas shkëmbinjve, të ngatërruara në ferra, të mbledhura pranë përroit. Kur agoi, mungonin vetëm dy. Dhe pas dy ditësh, u kthyen edhe ato vetë, duke blegëritur te porta e vathit.$s$,
    $s$Petriti nuk gënjeu më kurrë. Për shumë muaj, fshatarët e shikonin me dyshim. Por ai punonte, ndihmonte, mbante fjalën. Dhe pak nga pak, besimi u kthye. Kur u rrit, u bë një nga barinjtë më të besuar të fshatit. Dhe kur fëmijët e fshatit bënin shaka të tilla, ai u tregonte historinë e ujkut të vërtetë dhe u thoshte: «E vërteta është si një urë. Po e prishe, s'kalon më njeri mbi të.»$s$
  ]::text[],
  array['classic', 'lessons']::text[], 36, 108, 10, null,
  $s$<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 160 120"><defs><linearGradient id="gbariuqetherristeujku" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#CADAE8"/><stop offset="1" stop-color="#EFF4F8"/></linearGradient></defs><rect x="0" y="0" width="160" height="120" fill="url(#gbariuqetherristeujku)"/><circle cx="35.7" cy="20" r="8" fill="#FFF3D6"/><path d="M-14.3 100L25.7 33.5L65.7 100Z" fill="#A8BCCF"/><path d="M16.7 48.5L25.7 33.5L34.7 48.5L29.7 53.5L25.7 46.8L21.7 53.5Z" fill="#FFFFFF" opacity="0.9"/><path d="M81.2 100L121.2 33.7L161.2 100Z" fill="#A8BCCF"/><path d="M112.2 48.6L121.2 33.7L130.2 48.6L125.2 53.6L121.2 47L117.2 53.6Z" fill="#FFFFFF" opacity="0.9"/><path d="M40 100L80 50.5L120 100Z" fill="#7F99B0"/><path d="M71 61.6L80 50.5L89 61.6L84 65.4L80 60.4L76 65.4Z" fill="#FFFFFF" opacity="0.9"/><path d="M0 105.7Q40 98.4 80 104.4T160 105.8V120H0Z" fill="#7F99B0"/><ellipse cx="80" cy="98" rx="30" ry="3" fill="#000000" opacity="0.08"/><g transform="translate(43 33) scale(1.15)"><path d="M18 60Q14 44 22 32Q28 24 34 20L36 10L40 17Q46 13 52 6Q52 16 47 22Q44 32 46 44Q48 54 44 60Z" fill="#2F4357"/><path d="M18 54Q4 54 6 40Q12 50 22 48Z" fill="#2F4357"/><circle cx="43" cy="15" r="1.1" fill="#EFF4F8"/><path d="M54 4L58 1M56 8L61 7" fill="none" stroke="#2F4357" stroke-width="1.4" stroke-linecap="round" stroke-linejoin="round" opacity="0.6"/></g></svg>$s$,
  'published', false, 800, 'editor'
),
(
  $s$ari-i-turpshem$s$, 'sq', $s$Ari i turpshëm dhe festa e pyllit$s$,
  $s$Ariu Bruno është aq i turpshëm, sa fshihet sa herë që dikush i flet. Kur pylli bën festën e madhe të vjeshtës, ai gjen një mënyrë të vetën për t'u bashkuar.$s$,
  array[
    $s$Në një pyll të madh me ahe e me pisha, jetonte një ari i ri që quhej Bruno. Ishte i madh, me qime të trasha kafe e me putra të mëdha. Por kishte një zemër të vogël e të ndrojtur. Bruno ishte i turpshëm. Shumë i turpshëm. Kur dikush i fliste, fytyra i bëhej e nxehtë, zëri i humbiste dhe donte të fshihej pas pemës më të afërt. Ndonjëherë, edhe pse ishte i madh, përpiqej të fshihej pas një luleje.$s$,
    $s$Kafshët e pyllit nuk e kuptonin. «Pse Bruno s'flet kurrë?» pyeste ketri. «Ndoshta s'do të jetë shok me ne», thoshte lepuri. «Ndoshta është krenar, sepse është i madh», thoshte dhelpra. Por Bruno nuk ishte krenar. Do të donte shumë të ishte shok me ta. Thjesht s'dinte si.$s$,
    $s$Çdo vjeshtë, kafshët e pyllit bënin një festë të madhe në lëndinën e madhe, para se dimri të vinte. Sillnin ushqime, këndonin këngë, kërcenin rreth një zjarri të vogël dhe tregonin histori. Atë vit, ketri, që ishte organizatori, shkoi në çdo strofull e në çdo fole për t'i ftuar të gjithë. Shkoi edhe te shpella e Brunos.$s$,
    $s$«Bruno», tha ketri nga hyrja e shpellës, «të shtunën bëjmë festën e vjeshtës. Je i ftuar! Secili sjell diçka.» Bruno u fsheh në fund të shpellës dhe s'mundi të thoshte asnjë fjalë. Ketri priti pak, pastaj ngriti supet dhe iku. «Siç thashë», u tha të tjerëve, «Bruno s'do të vijë.»$s$,
    $s$Por Bruno donte të shkonte. Donte shumë. Gjithë javën mendoi për festën. Mendonte për këngët, për zjarrin, për kafshët që qeshnin bashkë. Dhe ndjente një dhimbje të vogël në zemër, sepse e dinte që do të ishte shumë i turpshëm për të shkuar. «Çfarë mund të bëj unë?» pyeste veten. «Nuk di të këndoj para të gjithëve. Nuk di të kërcej. Nuk di të tregoj histori. S'di as të them përshëndetje.»$s$,
    $s$Pastaj Bruno kujtoi diçka që dinte ta bënte mirë, shumë mirë: të gjente mjaltë. Me hundën e tij të madhe, e nuhaste mjaltin nga shumë larg, dhe dinte ku ishin koshere të bletëve të egra që kishin mjaltë të tepërt për të ndarë. Dhe kafshët e pyllit e donin shumë mjaltin, por rrallë e gjenin.$s$,
    $s$Gjithë ditën e premte, Bruno kërkoi mjaltë. Shkoi në vende ku s'kishte qenë kurrë, larg në pyll. U fliste bletëve me zë të ulët, dhe ato, që e njihnin si ari të butë, i dhanë pak nga mjalti i tyre. Bruno e mblodhi në gjethe të mëdha, të palosura si tasa, dhe në fund të ditës kishte një grumbull të madh me tasa me mjaltë të artë e të ndritshëm.$s$,
    $s$Të shtunën në mbrëmje, kur festa kishte filluar, Bruno u afrua ngadalë te lëndina. Dëgjoi muzikën, pa zjarrin, dëgjoi të qeshurat. Dhe zemra filloi t'i rrihte aq fort, sa mendoi se do t'i dilte nga gjoksi. Nuk mundi të hynte në lëndinë. Por kishte një plan. Pa e parë askush, i vendosi tasat me mjaltë në një rresht, në skaj të lëndinës, nën një pemë të madhe. Dhe u fsheh pas pemës.$s$,
    $s$Ishte lepuri i pari që i pa. «Shikoni!» thirri. «Mjaltë! Shumë mjaltë!» Të gjitha kafshët vrapuan. Nuhatën, provuan, dhe psherëtinë nga kënaqësia. «Është mjalti më i mirë që kam provuar ndonjëherë!» tha dhelpra. «Por kush e ka sjellë?» pyeti ketri. Askush s'e dinte.$s$,
    $s$Atëherë bufi i vjetër, që i sheh të gjitha nga lart, tha me zë të qetë: «Unë e di kush e ka sjellë. Ka kaluar gjithë ditën e djeshme duke e mbledhur, në vendet më të largëta të pyllit. Dhe tani është fshehur pas asaj peme, sepse është shumë i turpshëm për të hyrë.» Të gjitha kafshët u kthyen nga pema. Dhe panë, që dilte nga pas trungut, një vesh të madh kafe.$s$,
    $s$Ketri u afrua ngadalë, pa bërë zhurmë. «Bruno?» tha butë. «A je ti?» Bruno, pas pemës, tundi kokën. Nuk mund të fliste. Ketri nuk e nxitoi. U ul pranë rrënjëve të pemës, nga ana tjetër, dhe tha: «Faleminderit për mjaltin. Ishte dhurata më e bukur e festës. A do të vish të ulesh me ne? S'ke pse të flasësh. Mund të rrish vetëm pranë nesh.»$s$,
    $s$Bruno u mendua shumë gjatë. Pastaj, shumë ngadalë, doli nga pas pemës. Fytyra i ishte nxehur, putrat i dridheshin. Por kafshët nuk e shikuan me çudi. Lepuri i bëri vend pranë zjarrit. Dhelpra i dha një gjethe me arra. Dhe askush nuk e detyroi të fliste. Bruno u ul, dhe dëgjoi këngët, dhe shikoi zjarrin, dhe ndjeu ngrohtësinë e kafshëve rreth tij.$s$,
    $s$Bruno nuk tha asnjë fjalë gjithë mbrëmjen. Por kur festa po mbaronte dhe hëna kishte dalë mbi pisha, ketri u kthye nga ai dhe i tha: «Mirupafshim, Bruno.» Dhe Bruno, me një zë shumë të vogël, të ngjirur, që mezi dëgjohej, tha: «Mirupafshim.» Ishte fjala e parë që u kishte thënë ndonjëherë. Dhe të gjitha kafshët buzëqeshën. Sepse kishin kuptuar që Bruno s'ishte krenar, as i ftohtë. Ishte vetëm i turpshëm. Dhe që miqtë e vërtetë të presin, me durim, derisa të jesh gati.$s$
  ]::text[],
  array['emotions', 'friendship']::text[], 0, 84, 11, 'bear',
  $s$<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 160 120"><defs><linearGradient id="gariiturpshem" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#CBE0D3"/><stop offset="1" stop-color="#EDF3EC"/></linearGradient></defs><rect x="0" y="0" width="160" height="120" fill="url(#gariiturpshem)"/><circle cx="6.1" cy="74.6" r="16.9" fill="#8FB5A0" opacity="0.85"/><circle cx="20.3" cy="74.2" r="17.2" fill="#8FB5A0" opacity="0.85"/><path d="M33.9 38.6L43.9 100H23.9Z" fill="#5F8C76" opacity="0.85"/><path d="M49.9 49.4L59.9 100H39.9Z" fill="#8FB5A0" opacity="0.85"/><path d="M112.5 58.2L122.5 100H102.5Z" fill="#5F8C76" opacity="0.85"/><path d="M131.1 58.6L141.1 100H121.1Z" fill="#8FB5A0" opacity="0.85"/><circle cx="142.8" cy="75.4" r="16.4" fill="#8FB5A0" opacity="0.85"/><path d="M0 97.9Q40 92 80 98T160 100.3V120H0Z" fill="#5F8C76"/><ellipse cx="80" cy="98" rx="30" ry="3" fill="#000000" opacity="0.08"/><g transform="translate(43 33) scale(1.15)"><ellipse cx="28" cy="40" rx="20" ry="14" fill="#2C463B"/><circle cx="48" cy="28" r="10" fill="#2C463B"/><circle cx="42" cy="19" r="4" fill="#2C463B"/><circle cx="54" cy="19" r="4" fill="#2C463B"/><circle cx="42" cy="19" r="1.8" fill="#EDF3EC" opacity="0.6"/><circle cx="54" cy="19" r="1.8" fill="#EDF3EC" opacity="0.6"/><ellipse cx="56" cy="31" rx="5.5" ry="4" fill="#2C463B"/><circle cx="60" cy="30" r="1.8" fill="#EDF3EC"/><path d="M49 25.5q2 1.6 4 0" fill="none" stroke="#EDF3EC" stroke-width="1.2" stroke-linecap="round" stroke-linejoin="round"/><rect x="12" y="44" width="8" height="16" rx="4" fill="#2C463B"/><rect x="34" y="44" width="8" height="16" rx="4" fill="#2C463B"/></g></svg>$s$,
  'published', false, 810, 'editor'
