(
  $s$era-dhe-dielli$s$, 'sq', $s$Era e Veriut dhe Dielli$s$,
  $s$Sipas Ezopit: Era e Veriut dhe Dielli grinden se kush është më i fortë, dhe vendosin ta provojnë me një udhëtar me pallto. Fiton ai që s'e prisnin.$s$,
  array[
    $s$Shumë kohë më parë, lart në qiell, mbi male e mbi dete, jetonin Era e Veriut dhe Dielli. Era e Veriut ishte e fortë, e zhurmshme dhe krenare. Kur frynte, përkulte pemët, ngrinte valët dhe shkulte çatitë e kasolleve. Dielli ishte i qetë, i ngrohtë dhe i duruar. Çdo mëngjes dilte mbi male dhe çdo mbrëmje zbriste pas detit, pa nxituar kurrë.$s$,
    $s$Një ditë, Era e Veriut u mburr: «Unë jam më e forta në gjithë botën. Shiko çfarë mund të bëj!» Dhe fryu mbi një pyll, aq fort sa gjethet fluturuan si zogj të trembur. «Ti, Diell, vetëm rri aty dhe shkëlqen. Ç'forcë është kjo?»$s$,
    $s$Dielli buzëqeshi. «Forca nuk është vetëm zhurmë», tha. «Por nëse do, mund ta provojmë.» Shikuan poshtë, në tokë, dhe panë një udhëtar që ecte në një rrugë të gjatë mes fushave, i mbështjellë me një pallto të trashë leshi. «Ja», tha Dielli. «Kush e bën udhëtarin të heqë palltën, ai është më i forti.»$s$,
    $s$«Shumë lehtë!» tha Era e Veriut. «Kjo do të më marrë vetëm një minutë.» Dielli u fsheh pas një reje, që t'i linte vend. Dhe Era e Veriut mori frymë thellë, aq thellë sa iu fry gjoksi si një varkë me vela, dhe filloi të frynte.$s$,
    $s$Fryu një herë. Palltoja e udhëtarit u lëkund. Udhëtari e mbërtheu një kopsë më shumë. Era e Veriut fryu më fort. Kapela e udhëtarit fluturoi, dhe ai e kapi në ajër, pastaj e shtyu thellë në kokë. Era e Veriut u nxeh. Fryu me gjithë forcën që kishte: pemët u përkulën deri në tokë, pluhuri u ngrit si mjegull, zogjtë fluturonin mbrapsht.$s$,
    $s$Por sa më fort që frynte Era e Veriut, aq më fort e mbante udhëtari palltën. Mbërtheu të gjitha kopsat, ngriti jakën deri te veshët, e mbështolli palltën me të dyja krahët rreth trupit dhe vazhdoi të ecte, i përkulur përpara, kundër erës. «Ç'mot i tmerrshëm», mërmëriste. «Mirë që kam palltën.»$s$,
    $s$Më në fund, Era e Veriut u lodh. Fryu gjithnjë e më dobët, deri sa pushoi fare, e rraskapitur e me frymë të prerë. Udhëtari ende kishte palltën, të mbërthyer deri në fyt. «S'është e mundur», gulçoi Era. «Ky njeri ka një pallto prej guri.»$s$,
    $s$«Tani është radha ime», tha Dielli. Doli ngadalë nga pas resë, pa asnjë zhurmë. Dhe filloi të shkëlqente. Në fillim butë, si në një mëngjes pranvere. Udhëtari ngriti kokën dhe ndjeu ngrohtësinë në fytyrë. Ndaloi për një çast dhe buzëqeshi. Pastaj zgjidhi kopsën e sipërme.$s$,
    $s$Dielli shkëlqeu pak më fort, si në një paradite qershori. Udhëtari ndjeu ngrohtë. Zgjidhi edhe dy kopsa të tjera. Uli jakën. Fshiu ballin me dorë. Dielli shkëlqeu edhe pak më shumë, i ngrohtë si në mesditë korriku, dhe zogjtë filluan të këndonin, dhe bletët filluan të fluturonin nëpër lule.$s$,
    $s$Udhëtari psherëtiu. «Uf, sa nxehtë u bë!» Dhe zgjidhi të gjitha kopsat, hoqi palltën, e palosi në krah dhe vazhdoi të ecte i lehtë, në këmishë, duke fishkëllyer një këngë. Pastaj pa një pemë me hije pranë rrugës, u ul nën të dhe e përdori palltën si jastëk.$s$,
    $s$Era e Veriut nuk tha asgjë për një kohë të gjatë. Pastaj, me një zë shumë më të vogël se zakonisht, pyeti: «Si e bëre? Unë fryva me gjithë forcën që kam, dhe ai e mbajti palltën më fort. Ti thjesht shkëlqeve, dhe ai e hoqi vetë.»$s$,
    $s$«Pikërisht kjo», tha Dielli. «Kur e shtyn dikë me forcë, ai mbyllet dhe mbrohet. Kur e ngroh me butësi, ai hapet vetë.» Era e Veriut u mendua gjatë. Dhe që nga ajo ditë, ndonjëherë, në pranverë, Era e Veriut fryn butë, shumë butë, sa për të lëkundur lulet. Dhe njerëzit e quajnë flladi.$s$,
    $s$Mbaje mend këtë histori, kur dikush nuk të dëgjon. Ndoshta s'duhet të bërtasësh më fort. Ndoshta mjafton të jesh më i ngrohtë. Sepse butësia, shpesh, është forca më e madhe nga të gjitha.$s$
  ]::text[],
  array['classic', 'lessons']::text[], 36, 108, 8, null,
  $s$<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 160 120"><defs><linearGradient id="geradhedielli" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#BBDAE4"/><stop offset="1" stop-color="#EAF4F2"/></linearGradient></defs><rect x="0" y="0" width="160" height="120" fill="url(#geradhedielli)"/><circle cx="33.3" cy="22" r="10" fill="#FFF3D6"/><ellipse cx="118" cy="26" rx="14" ry="5" fill="#FFFFFF" opacity="0.85"/><circle cx="114" cy="22" r="6" fill="#FFFFFF" opacity="0.85"/><circle cx="123" cy="21" r="5" fill="#FFFFFF" opacity="0.85"/><path d="M0 88.8Q40 76.8 80 88.8T160 81.4V120H0Z" fill="#A6CDB4"/><path d="M0 98.5Q40 93.6 80 101.6T160 99.1V120H0Z" fill="#86B897"/><ellipse cx="80" cy="98" rx="30" ry="3" fill="#000000" opacity="0.08"/><g transform="translate(43 33) scale(1.15)"><path d="M4 22H40Q50 22 50 14Q50 6 42 8M4 34H52Q62 34 62 44Q62 52 54 50M10 46H34Q42 46 42 54" fill="none" stroke="#35504B" stroke-width="2.6" stroke-linecap="round" stroke-linejoin="round"/><ellipse cx="54" cy="20" rx="4" ry="2" fill="#7DA86B" transform="rotate(30 54 20)"/><ellipse cx="20" cy="54" rx="4" ry="2" fill="#E7B04B" transform="rotate(-30 20 54)"/></g></svg>$s$,
  'published', false, 820, 'editor'
),
(
  $s$rreqebulli-i-malit$s$, 'sq', $s$Rrëqebulli i fshehtë i malit$s$,
  $s$Iliri dhe babai i tij, roje pyjesh, kërkojnë rrëqebullin e Ballkanit, kafshën më të fshehtë të maleve shqiptare. Ai i sheh ata shumë kohë para se ta shohin ata atë.$s$,
  array[
    $s$Babai i Ilirit ishte roje pyjesh në malet e Shebenikut, aty ku pyjet e ahut janë aq të dendur sa edhe në mesditë duket sikur është mbrëmje. Çdo të shtunë, Iliri i shkonte pas, me çantën e vogël në shpinë, një shishe me ujë dhe një fletore ku vizatonte gjurmët e kafshëve.$s$,
    $s$Kishte vizatuar shumë gjurmë: gjurmët e drerit, si dy pika loti të ngjitura; gjurmët e ujkut, me katër gishta e me thonj; gjurmët e ariut, të mëdha si këmbë njeriu. Por kishte një gjurmë që s'e kishte gjetur kurrë: atë të rrëqebullit.$s$,
    $s$«Rrëqebulli i Ballkanit është kafsha më e fshehtë e maleve tona», i tregonte babai. «Është si një mace e madhe, me veshë me xhufka të zeza në majë, me bisht të shkurtër e me sy si qelibar. Kanë mbetur shumë pak, ndoshta më pak se pesëdhjetë në gjithë Ballkanin. Unë punoj këtu prej njëzet vjetësh, dhe e kam parë me sytë e mi vetëm një herë.»$s$,
    $s$Atë pranverë, babai solli në mal disa kamera të vogla, që fotografonin vetë kur kalonte ndonjë kafshë. I lidhën pas trungjeve të ahut, në vende të fshehta, pranë shtigjeve të kafshëve. «Tani do të presim», tha babai. «Mali s'nxiton kurrë.»$s$,
    $s$Çdo javë ktheheshin dhe shikonin fotot. Kishte derra të egër që gërmonin me hundë, një dhelpër që i bënte kamerës ballë sikur pozonte, një ketër që kishte kafshuar rripin e kamerës dhe një ari të madh që ishte kruar me shpinë pas pemës, aq gjatë sa kishte bërë dyzet foto. Iliri qeshte me zë. Por rrëqebull, asnjë.$s$,
    $s$Vera kaloi kështu. Iliri filloi të mërzitej. «Ndoshta s'ka mbetur më asnjë», i tha babait një ditë, ndërsa pushonin pranë një përroi. Babai e vështroi me buzëqeshje. «Apo ndoshta ai na sheh ne shumë më mirë se ne atë. Rrëqebulli s'është i fshehtë sepse ka frikë. Është i fshehtë sepse është i mençur. E di që njerëzit i kanë bërë dëm dikur, dhe ka mësuar të mos besojë.»$s$,
    $s$Iliri mendoi për këtë gjatë gjithë rrugës së kthimit. Atë natë, në shtëpi, shkroi në fletore: «Ndoshta rrëqebulli s'ka nevojë që ta shohim ne. Ndoshta ka nevojë vetëm që ta lëmë të qetë.»$s$,
    $s$Në vjeshtë, kur gjethet e ahut u bënë portokalli e të kuqe, babai dhe Iliri u ngjitën për të marrë kamerat, para se të binte bora. Kamera e fundit ishte në vendin më të largët, pranë një shkëmbi të madh me myshk. Babai e hapi dhe filloi të shikonte fotot një nga një, dhe papritur ndaloi.$s$,
    $s$«Ilir», pëshpëriti. «Eja shpejt.» Në ekranin e vogël, në një foto të bërë natën, me dritë gri, ishte një mace e madhe me xhufka në veshë. Rrëqebulli! Dhe pas tij, me hapa të ngatërruar, vinin dy të vegjël me pika, me veshë të mëdhenj e me sy të rrumbullakët, që i shkonin pas nënës si dy topa leshi.$s$,
    $s$Iliri mbajti frymën. Shikuan foto pas fotoje: nëna që nuhaste ajrin, të vegjlit që luanin me një fletë, nëna që shikonte drejt kamerës me sytë e saj të verdhë, e qetë, sikur e dinte. «Kanë lindur këtë pranverë», tha babai me zë që i dridhej pak. «Familja po rritet.»$s$,
    $s$Ndërsa po zbrisnin, Iliri ndjeu diçka. Si një shikim pas shpine. Ktheu kokën ngadalë drejt shkëmbit. Lart, mes gjetheve të kuqe, iu duk se pa dy majë veshësh me xhufka të zeza. Vetëm për një çast. Pastaj asgjë. Vetëm era që lëvizte degët.$s$,
    $s$Nuk i tha gjë babait. E mbajti për vete, si një sekret të çmuar. Por kur u kthye në shtëpi, hapi fletoren dhe vizatoi, në faqen e fundit, dy veshë me xhufka që dilnin nga gjethet. Poshtë shkroi: «E pashë. Dhe ai më pa mua. Dhe asnjëri prej nesh s'pati frikë.»$s$,
    $s$Sonte, ndërsa ti fle, lart në malet e Shebenikut, një nënë rrëqebull po u bën roje dy të vegjëlve të saj në një strofull mes shkëmbinjve. Ndoshta s'do ta shohësh kurrë. Por është aty. Dhe mali është më i bukur, sepse ajo është aty.$s$
  ]::text[],
  array['nature', 'lessons']::text[], 48, 120, 9, null,
  $s$<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 160 120"><defs><linearGradient id="grreqebulliimalit" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#CBE0D3"/><stop offset="1" stop-color="#EDF3EC"/></linearGradient></defs><rect x="0" y="0" width="160" height="120" fill="url(#grreqebulliimalit)"/><path d="M8.8 56.4L18.8 100H-1.2Z" fill="#5F8C76" opacity="0.85"/><circle cx="19.9" cy="76.1" r="15.9" fill="#8FB5A0" opacity="0.85"/><circle cx="36" cy="78.7" r="14.2" fill="#8FB5A0" opacity="0.85"/><path d="M45.4 44.8L55.4 100H35.4Z" fill="#8FB5A0" opacity="0.85"/><path d="M116.1 45.8L126.1 100H106.1Z" fill="#5F8C76" opacity="0.85"/><path d="M132.7 53.7L142.7 100H122.7Z" fill="#8FB5A0" opacity="0.85"/><circle cx="147.7" cy="69.9" r="20.1" fill="#8FB5A0" opacity="0.85"/><path d="M0 99.4Q40 94 80 100T160 100.6V120H0Z" fill="#5F8C76"/><ellipse cx="80" cy="98" rx="30" ry="3" fill="#000000" opacity="0.08"/><g transform="translate(43 33) scale(1.15)"><path d="M16 60Q12 44 18 34Q22 26 30 26Q38 26 42 34Q48 46 44 60Z" fill="#2C463B"/><circle cx="30" cy="20" r="11" fill="#2C463B"/><path d="M20 14L20 1L27 11Z" fill="#2C463B"/><path d="M40 14L40 1L33 11Z" fill="#2C463B"/><path d="M20 2L20 -2M40 2L40 -2" fill="none" stroke="#2C463B" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"/><ellipse cx="26" cy="19" rx="2" ry="2.6" fill="#EDF3EC"/><ellipse cx="34" cy="19" rx="2" ry="2.6" fill="#EDF3EC"/><path d="M28.5 24L30 26L31.5 24Z" fill="#EDF3EC"/><path d="M16 25L6 23M16 27L6 28M44 25L54 23M44 27L54 28" fill="none" stroke="#2C463B" stroke-width="1" stroke-linecap="round" stroke-linejoin="round" opacity="0.8"/><path d="M44 56Q54 56 52 48" fill="#2C463B"/></g></svg>$s$,
  'published', false, 830, 'editor'
),
(
  $s$bretkosa-qe-donte-te-kendonte$s$, 'sq', $s$Bretkosa që donte të këndonte në kor$s$,
  $s$Bretkosa Kroki ka zërin më të ngjirur të pellgut dhe s'e pranojnë në korin e verës. Por një natë, kur bie mjegulla, zëri i saj i ndryshëm është pikërisht ai që duhet.$s$,
  array[
    $s$Në një pellg të madh pranë një fshati, jetonin shumë bretkosa. Dhe çdo verë, kur netët ishin të ngrohta, bretkosat bënin një kor. Mblidheshin mbi gjethet e zambakëve të ujit dhe këndonin gjithë natën, me zëra të ëmbël e të harmonishëm: kroak-kroak, kroak-kroak. Fshatarët hapnin dritaret për t'i dëgjuar.$s$,
    $s$Bretkosa Kroki donte shumë të këndonte në kor. Por kishte një problem: zëri i saj ishte ndryshe. Nuk ishte i ëmbël e i butë si i bretkosave të tjera. Ishte i thellë, i ngjirur e shumë i fortë: KRRROOOAK! Kur këndonte Kroki, zëri i saj dëgjohej mbi të gjithë të tjerët, si një daulle në mes të flautave.$s$,
    $s$«Më vjen keq, Kroki», i tha drejtuesja e korit, një bretkosë e vjetër jeshile me syze. «Zëri yt është shumë i fortë. Prish harmoninë. Ndoshta mund të na dëgjosh nga bregu.» Kroki uli kokën dhe u ul në breg, mes kallamave, dhe dëgjoi korin gjithë natën, pa kënduar.$s$,
    $s$Kroki provoi të ndryshonte zërin. Provoi të këndonte më butë, por zëri i dilte si një fishkëllimë e çuditshme. Provoi të këndonte më hollë, por i dilte si një kollë. Provoi të këndonte vetëm me gojë gjysmë të hapur, por i dilte si një gërhitje. Dhe çdo herë, bretkosat e tjera qeshnin pak. Jo me të keq, por qeshnin.$s$,
    $s$«Pse s'jam si të tjerat?» pyeti Kroki një natë gjyshen e saj, një bretkosë e plakur që jetonte në fund të pellgut. Gjyshja e dëgjoi zërin e saj të thellë dhe buzëqeshi. «Zëri yt është si i gjyshit tënd», tha. «Edhe ai kishte zë të fortë. Dhe e di çfarë? Një natë, ai shpëtoi gjithë pellgun.» «Si?» pyeti Kroki. Por gjyshja kishte rënë në gjumë, sepse ishte shumë e plakur.$s$,
    $s$Kalonin javët. Një natë në fund të verës, pellgu u mbulua papritur nga një mjegull e dendur. Ishte aq e dendur, sa bretkosat s'shihnin as njëra-tjetrën. Dhe disa prej bretkosave të reja, që kishin dalë larg pellgut për të gjuajtur mushkonja në livadh, nuk e gjenin dot rrugën e kthimit.$s$,
    $s$«Ndihmë!» thërrisnin bretkosat e humbura nga livadhi. «S'shohim asgjë! Ku është pellgu?» Bretkosat e korit filluan të këndonin, që t'u tregonin rrugën. Por zërat e tyre ishin të ëmbël e të butë, dhe mjegulla i përpinte. Nuk arrinin deri në livadh. Bretkosat e humbura vazhdonin të thërrisnin, gjithnjë e më të trembura.$s$,
    $s$Atëherë Kroki kujtoi fjalët e gjyshes. Kërceu mbi gjethen më të lartë të pellgut, mori frymë aq thellë sa iu fry gusha si një tullumbace, dhe këndoi me gjithë forcën: KRRROOOOAAAK! Zëri i saj i thellë e i fortë çau mjegullën si një fener. Shkoi larg, shumë larg, mbi livadh, deri te bretkosat e humbura.$s$,
    $s$«E dëgjuam!» thirrën bretkosat e humbura. «Atje është pellgu!» Dhe filluan të kërcenin drejt zërit të Krokit. Kroki vazhdoi të këndonte, pa pushim, KRRROOOAK, KRRROOOAK, edhe kur iu ngjir fyti, edhe kur iu lodhën gushat. Dhe një nga një, nga mjegulla dolën bretkosat e humbura, të lagura e të trembura, por shëndoshë e mirë.$s$,
    $s$Kur doli edhe e fundit, një bretkosë e vogël, e vockël, Kroki pushoi së kënduari dhe u ul e rraskapitur mbi gjethe. Gjithë pellgu ishte i heshtur. Pastaj drejtuesja e korit, bretkosa e vjetër me syze, kërceu deri te gjethja e Krokit. «Kroki», tha, «mendova se zëri yt ishte shumë i fortë. Por sonte ishte pikërisht zëri që na duhej. Ishte i vetmi që arriti t'i gjente.»$s$,
    $s$Të nesërmen në mbrëmje, kur bretkosat u mblodhën për korin, drejtuesja i tha Krokit: «A do të këndosh me ne?» «Por zëri im prish harmoninë», tha Kroki. «Jo», tha drejtuesja. «Kemi gabuar. Çdo kor ka nevojë për zëra të ndryshëm. Për zëra të hollë e të ëmbël, por edhe për një zë të thellë e të fortë, që mban gjithë korin bashkë. Ti do të jesh basi ynë.»$s$,
    $s$Dhe kështu, atë natë, Kroki këndoi në kor për herë të parë. Bretkosat e tjera këndonin kroak-kroak të ëmbla, dhe Kroki, poshtë tyre, këndonte KRRROOOAK të thellë, si themeli i një shtëpie. Dhe për habinë e të gjithëve, kori tingëllonte më bukur se kurrë. Ishte më i plotë, më i pasur, më i gjallë. Fshatarët hapën dritaret dhe thanë: «Sonte bretkosat këndojnë ndryshe. Më bukur.»$s$,
    $s$Gjyshja e Krokit dëgjoi nga fundi i pellgut dhe buzëqeshi. Dhe Kroki kuptoi atë që kishte dashur t'i thoshte gjyshja: që zëri i saj nuk ishte i gabuar. Ishte thjesht i ndryshëm. Dhe që ndonjëherë, ajo që na bën të ndryshëm është pikërisht ajo që na bën të nevojshëm. Sonte, nëse dëgjon bretkosat në ndonjë pellg, dëgjo mirë. Ndoshta do ta dallosh Krokin, me zërin e saj të thellë, që mban gjithë korin bashkë.$s$
  ]::text[],
  array['emotions', 'lessons']::text[], 0, 84, 10, null,
  $s$<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 160 120"><defs><linearGradient id="gbretkosaqedonteteken" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#1E3446"/><stop offset="1" stop-color="#2E5566"/></linearGradient></defs><rect x="0" y="0" width="160" height="120" fill="url(#gbretkosaqedonteteken)"/><circle cx="34" cy="20.3" r="1.3" fill="#F3EBD9" opacity="0.7"/><circle cx="12.1" cy="35.9" r="1.2" fill="#F3EBD9" opacity="0.7"/><path d="M140.2 17.5Q140.2 19.9 142.6 19.9Q140.2 19.9 140.2 22.299999999999997Q140.2 19.9 137.79999999999998 19.9Q140.2 19.9 140.2 17.5Z" fill="#F3EBD9" opacity="0.9"/><circle cx="133.4" cy="25.3" r="1" fill="#F3EBD9" opacity="0.7"/><path d="M104.3 9.600000000000001Q104.3 13.3 108 13.3Q104.3 13.3 104.3 17Q104.3 13.3 100.6 13.3Q104.3 13.3 104.3 9.600000000000001Z" fill="#F3EBD9" opacity="0.9"/><circle cx="75.5" cy="7.4" r="1.4" fill="#F3EBD9" opacity="0.7"/><circle cx="132.1" cy="22" r="11" fill="#F3EBD9"/><circle cx="126.1" cy="18" r="10" fill="#1E3446"/><path d="M0 83.7Q40 79 80 89T160 89.3V120H0Z" fill="#24455A"/><path d="M0 96.5Q40 91.5 80 99.5T160 98V120H0Z" fill="#1A3344"/><ellipse cx="80" cy="98" rx="30" ry="3" fill="#000000" opacity="0.08"/><g transform="translate(43 33) scale(1.15)"><ellipse cx="32" cy="46" rx="18" ry="11" fill="#F3EBD9"/><circle cx="23" cy="34" r="6" fill="#F3EBD9"/><circle cx="41" cy="34" r="6" fill="#F3EBD9"/><circle cx="23" cy="34" r="3" fill="#24455A"/><circle cx="41" cy="34" r="3" fill="#24455A"/><circle cx="23" cy="34" r="1.4" fill="#F3EBD9"/><circle cx="41" cy="34" r="1.4" fill="#F3EBD9"/><path d="M24 48Q32 53 40 48" fill="none" stroke="#24455A" stroke-width="1.4" stroke-linecap="round" stroke-linejoin="round"/><ellipse cx="14" cy="56" rx="7" ry="3" fill="#F3EBD9"/><ellipse cx="50" cy="56" rx="7" ry="3" fill="#F3EBD9"/><ellipse cx="32" cy="60" rx="26" ry="2" fill="#7DA86B" opacity="0.5"/></g></svg>$s$,
